input.content:
/* RevvLot — Retro 90s Web Used Car Marketplace */
@import url('https://fonts.googleapis.com/css2?family=Press+Start+2P&family=IBM+Plex+Mono:wght@400;500;700&family=Archivo+Black&family=Archivo:wght@800&display=swap');

:root {
  --lot-black: #0A0A0A;
  --revv-cyan: #00F5FF;
  --turbo-purple: #CC00FF;
  --nitro-lime: #AAFF00;
  --screen-fog: #1C1C2E;
  --pixel-magenta: #FF2D78;
  --crt-white: #E8F0F2;
  --gridline-gray: #2E2E44;

  --font-pixel: 'Press Start 2P', monospace;
  --font-mono: 'IBM Plex Mono', monospace;
  --font-accent: 'Archivo Black', 'Archivo', sans-serif;
}

* { box-sizing: border-box; }
html, body {
  margin: 0; padding: 0;
  background: var(--lot-black);
  color: var(--crt-white);
  font-family: var(--font-mono);
  font-size: 16px;
  line-height: 1.75;
  overflow-x: hidden;
}

a { color: var(--revv-cyan); text-decoration: none; }
a:hover { text-decoration: underline; }

img, svg { display: block; max-width: 100%; }

h1, h2, h3, h4 {
  font-family: var(--font-pixel);
  text-transform: uppercase;
  margin: 0;
  line-height: 1.4;
}

p { margin: 0; }

/* ============= LAYOUT ============= */
.container {
  width: 100%;
  max-width: 1280px;
  margin: 0 auto;
  padding: 0 64px;
}

.full-bleed { width: 100%; }

.eyebrow {
  font-family: var(--font-accent);
  text-transform: uppercase;
  letter-spacing: 0.12em;
  font-size: 11px;
  color: var(--revv-cyan);
  display: inline-flex;
  align-items: center;
  gap: 12px;
  margin: 0;
}
.eyebrow::before {
  content: '';
  display: inline-block;
  width: 32px; height: 2px;
  background: currentColor;
}
.eyebrow.no-bar::before { display: none; }
.eyebrow.lime { color: var(--nitro-lime); }
.eyebrow.purple { color: var(--turbo-purple); }
.eyebrow.magenta { color: var(--pixel-magenta); }
.eyebrow.dark { color: var(--lot-black); }

/* ============= NAV ============= */
.nav {
  background: var(--lot-black);
  border-bottom: 2px solid var(--turbo-purple);
  padding: 14px 64px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  position: sticky;
  top: 0;
  z-index: 100;
}
.nav-logo {
  font-family: var(--font-pixel);
  color: var(--revv-cyan);
  font-size: 18px;
  letter-spacing: 1px;
  display: flex;
  align-items: center;
  gap: 10px;
  text-decoration: none;
}
.nav-logo .pixel-spark {
  width: 14px; height: 14px;
  background: var(--nitro-lime);
  box-shadow:
    -7px 0 0 var(--pixel-magenta),
    7px 0 0 var(--turbo-purple);
}
.nav-links {
  display: flex; gap: 28px;
  list-style: none;
  margin: 0; padding: 0;
}
.nav-links a {
  font-family: var(--font-accent);
  text-transform: uppercase;
  letter-spacing: 0.12em;
  font-size: 11px;
  color: var(--crt-white);
  text-decoration: none;
}
.nav-links a:hover, .nav-links a.active { color: var(--revv-cyan); text-decoration: none; }
.nav-cta {
  font-family: var(--font-accent);
  text-transform: uppercase;
  letter-spacing: 0.12em;
  font-size: 10px;
  background: var(--revv-cyan);
  color: var(--lot-black);
  padding: 10px 16px;
  border: 2px solid var(--revv-cyan);
  box-shadow: 4px 4px 0 var(--lot-black);
}

/* ============= BUTTONS ============= */
.btn {
  display: inline-block;
  font-family: var(--font-accent);
  text-transform: uppercase;
  letter-spacing: 0.12em;
  font-size: 11px;
  padding: 14px 28px;
  border: 3px solid var(--revv-cyan);
  background: var(--revv-cyan);
  color: var(--lot-black);
  cursor: pointer;
  text-decoration: none;
  box-shadow: 4px 4px 0 var(--lot-black);
  transition: transform 0.08s linear, box-shadow 0.08s linear;
}
.btn:hover { transform: translate(2px,2px); box-shadow: 2px 2px 0 var(--lot-black); text-decoration: none; }
.btn-secondary {
  background: transparent;
  border-color: var(--crt-white);
  color: var(--crt-white);
  box-shadow: 4px 4px 0 var(--gridline-gray);
}
.btn-secondary:hover { box-shadow: 2px 2px 0 var(--gridline-gray); }
.btn-purple {
  background: var(--turbo-purple);
  border-color: var(--turbo-purple);
  color: var(--crt-white);
}
.btn-magenta {
  background: var(--pixel-magenta);
  border-color: var(--pixel-magenta);
  color: var(--crt-white);
}
.btn-lime {
  background: var(--nitro-lime);
  border-color: var(--lot-black);
  color: var(--lot-black);
}
.btn-outline {
  background: transparent;
  border-color: var(--revv-cyan);
  color: var(--revv-cyan);
  box-shadow: 4px 4px 0 var(--gridline-gray);
}
.btn-outline:hover { background: var(--revv-cyan); color: var(--lot-black); }
.btn-dark-on-purple {
  background: var(--lot-black);
  border-color: var(--lot-black);
  color: var(--crt-white);
}
.btn-dark-on-purple:hover { background: var(--revv-cyan); color: var(--lot-black); }

.btn-row {
  display: flex; gap: 16px; flex-wrap: wrap;
  margin-top: 32px;
}

/* ============= STRUCTURAL DIVIDERS ============= */
.purple-rule {
  height: 8px;
  width: 100%;
  background:
    repeating-linear-gradient(
      90deg,
      var(--turbo-purple) 0 8px,
      var(--turbo-purple) 8px 16px
    );
}
.checker-strip {
  height: 16px;
  width: 100%;
  background-image:
    linear-gradient(45deg, var(--nitro-lime) 25%, transparent 25%, transparent 75%, var(--nitro-lime) 75%),
    linear-gradient(45deg, var(--nitro-lime) 25%, var(--lot-black) 25%, var(--lot-black) 75%, var(--nitro-lime) 75%);
  background-size: 16px 16px;
  background-position: 0 0, 8px 8px;
}
.checker-strip.gray {
  background-image:
    linear-gradient(45deg, var(--gridline-gray) 25%, transparent 25%, transparent 75%, var(--gridline-gray) 75%),
    linear-gradient(45deg, var(--gridline-gray) 25%, var(--lot-black) 25%, var(--lot-black) 75%, var(--gridline-gray) 75%);
}

/* ============= SECTION DEFAULTS ============= */
section {
  position: relative;
  padding: 80px 64px;
}
section.tight { padding: 48px 64px; }
section.huge { padding: 96px 64px; }
section.dark { background: var(--lot-black); }
section.fog { background: var(--screen-fog); }
section.purple { background: var(--turbo-purple); }
section.magenta { background: var(--pixel-magenta); }

.section-title {
  font-family: var(--font-pixel);
  font-size: 26px;
  color: var(--crt-white);
  margin: 16px 0 0;
  line-height: 1.4;
}
.section-title.cyan { color: var(--revv-cyan); }
.section-title.dark { color: var(--lot-black); }

.section-sub {
  margin-top: 16px;
  color: var(--crt-white);
  max-width: 640px;
  font-size: 15px;
  line-height: 1.75;
  opacity: 0.85;
}
.section-sub.dark { color: var(--lot-black); opacity: 0.85; }

/* ============= HERO (HOME) ============= */
.hero {
  background: var(--lot-black);
  padding: 80px 64px 60px;
  position: relative;
  overflow: hidden;
}
.hero::before {
  content: '';
  position: absolute; inset: 0;
  background-image:
    linear-gradient(45deg, var(--gridline-gray) 25%, transparent 25%, transparent 75%, var(--gridline-gray) 75%),
    linear-gradient(45deg, var(--gridline-gray) 25%, transparent 25%, transparent 75%, var(--gridline-gray) 75%);
  background-size: 8px 8px;
  background-position: 0 0, 4px 4px;
  opacity: 0.04;
  pointer-events: none;
}
.hero-grid {
  display: grid;
  grid-template-columns: 7fr 5fr;
  gap: 0;
  align-items: center;
  position: relative;
  z-index: 2;
}
.hero-headline {
  font-family: var(--font-pixel);
  font-size: 72px;
  line-height: 1.1;
  color: var(--revv-cyan);
  text-transform: uppercase;
  white-space: nowrap;
  margin: 24px 0 0;
}
.hero-headline .line-2 {
  color: var(--crt-white);
  display: block;
}
.hero-sub {
  margin-top: 24px;
  font-family: var(--font-mono);
  font-size: 16px;
  color: var(--crt-white);
  max-width: 520px;
  line-height: 1.75;
}
.hero-illustration {
  position: relative;
  width: 100%;
  max-width: 680px;
  margin-left: auto;
}

/* Browser window chrome */
.browser-window {
  border: 2px solid var(--revv-cyan);
  background: var(--screen-fog);
  box-shadow: 0 0 16px rgba(0,245,255,0.25);
}
.browser-bar {
  background: var(--screen-fog);
  border-bottom: 2px solid var(--revv-cyan);
  padding: 8px 12px;
  display: flex;
  align-items: center;
  gap: 10px;
}
.browser-dots { display: flex; gap: 6px; }
.browser-dot {
  width: 10px; height: 10px;
  border-radius: 50%;
}
.dot-magenta { background: var(--pixel-magenta); }
.dot-lime { background: var(--nitro-lime); }
.dot-cyan { background: var(--revv-cyan); }
.browser-url {
  flex: 1;
  font-family: var(--font-mono);
  font-size: 12px;
  color: var(--crt-white);
  background: var(--lot-black);
  padding: 4px 10px;
  border: 1px solid var(--gridline-gray);
}
.browser-content { padding: 0; }

/* ============= STATS ============= */
.stats-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  margin-top: 24px;
  position: relative;
  z-index: 2;
}
.stat-card {
  padding: 20px 28px 20px 28px;
  border-top: 2px solid var(--revv-cyan);
  border-right: 1px solid var(--gridline-gray);
  background: transparent;
}
.stat-card:last-child { border-right: none; }
.stat-cat {
  font-family: var(--font-accent);
  font-size: 9px;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--gridline-gray);
}
.stat-num {
  font-family: var(--font-mono);
  font-weight: 700;
  font-size: 56px;
  color: var(--nitro-lime);
  line-height: 1.05;
  margin-top: 6px;
}
.stat-desc {
  font-size: 13px;
  color: var(--crt-white);
  line-height: 1.6;
  margin-top: 12px;
  opacity: 0.9;
}
.stats-bg {
  position: relative;
  background: var(--screen-fog);
}
.stats-bg::before {
  content: '';
  position: absolute; inset: 0;
  background-image:
    linear-gradient(45deg, var(--gridline-gray) 25%, transparent 25%, transparent 75%, var(--gridline-gray) 75%),
    linear-gradient(45deg, var(--gridline-gray) 25%, transparent 25%, transparent 75%, var(--gridline-gray) 75%);
  background-size: 16px 16px;
  background-position: 0 0, 8px 8px;
  opacity: 0.12;
  pointer-events: none;
}

/* ============= FEATURE GRID (HOME) ============= */
.feature-block {
  display: grid;
  grid-template-columns: 4fr 8fr;
  gap: 0;
}
.feature-text {
  padding-right: 32px;
  border-right: 2px solid var(--turbo-purple);
}
.feature-text .section-title { font-size: 20px; }
.feature-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 16px;
  padding-left: 32px;
}
.feature-card {
  position: relative;
  background: var(--screen-fog);
  border: 2px solid var(--gridline-gray);
  padding: 28px;
  transition: border-color 0.15s linear;
}
.feature-card:hover { border-top-color: var(--revv-cyan); }
.feature-card.offset { transform: translateY(16px); }
.feature-icon {
  width: 40px; height: 40px;
  color: var(--revv-cyan);
}
.feature-card h3 {
  font-family: var(--font-pixel);
  font-size: 12px;
  color: var(--crt-white);
  margin-top: 16px;
  line-height: 1.5;
}
.feature-card p {
  font-size: 14px;
  margin-top: 12px;
  line-height: 1.7;
  color: var(--crt-white);
}
.feature-card::after {
  content: '';
  position: absolute;
  bottom: 8px; right: 8px;
  width: 4px; height: 4px;
  background: var(--turbo-purple);
}

/* ============= TIMELINE (HOME) ============= */
.timeline-row {
  margin-top: 32px;
  position: relative;
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 16px;
}
.timeline-row::before {
  content: '';
  position: absolute;
  left: 24px; right: 24px;
  top: 24px;
  height: 2px;
  background-image:
    repeating-linear-gradient(90deg, var(--revv-cyan) 0 8px, transparent 8px 14px);
  z-index: 1;
}
.tl-step { position: relative; z-index: 2; }
.tl-node {
  width: 48px; height: 48px;
  border: 3px solid var(--revv-cyan);
  background: var(--screen-fog);
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-mono);
  font-weight: 700;
  font-size: 20px;
  color: var(--nitro-lime);
  border-radius: 50%;
}
.tl-step h4 {
  margin-top: 20px;
  font-family: var(--font-accent);
  font-size: 11px;
  letter-spacing: 0.12em;
  color: var(--revv-cyan);
  text-transform: uppercase;
}
.tl-step p {
  margin-top: 8px;
  font-size: 14px;
  color: var(--crt-white);
}

/* ============= TESTIMONIALS ============= */
.testimonials-stack {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
  margin-top: 28px;
  align-items: start;
}
.tcard-1 { transform: translateY(0); }
.tcard-2 { transform: translateY(32px); }
.tcard-3 { transform: translateY(48px); }
.testimonial-card {
  position: relative;
  background: var(--lot-black);
  border: 2px solid var(--crt-white);
  padding: 28px;
  color: var(--crt-white);
}
.testimonial-card .quote-mark {
  position: absolute;
  top: -28px; left: 16px;
  font-family: var(--font-mono);
  color: var(--nitro-lime);
  font-size: 56px;
  line-height: 1;
}
.testimonial-card p {
  font-size: 14px;
  line-height: 1.75;
  color: var(--crt-white);
}
.testimonial-card .attribution {
  margin-top: 16px;
  font-family: var(--font-accent);
  letter-spacing: 0.12em;
  font-size: 10px;
  text-transform: uppercase;
  color: var(--revv-cyan);
}
.rating-sticker {
  position: absolute;
  bottom: -14px; right: -14px;
  background: var(--pixel-magenta);
  border: 3px solid var(--pixel-magenta);
  color: var(--crt-white);
  font-family: var(--font-accent);
  font-size: 9px;
  padding: 4px 10px;
  letter-spacing: 0.12em;
  transform: rotate(4deg);
}

/* ============= FOOTER ============= */
.site-footer {
  background: var(--lot-black);
  border-top: 8px solid var(--turbo-purple);
  padding: 48px 64px 36px;
  color: var(--crt-white);
}
.footer-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr;
  gap: 32px;
  margin-bottom: 32px;
}
.footer-brand .nav-logo { font-size: 22px; margin-bottom: 12px; }
.footer-grid h4 {
  font-family: var(--font-accent);
  font-size: 11px;
  letter-spacing: 0.12em;
  color: var(--nitro-lime);
  text-transform: uppercase;
  margin: 0 0 12px;
}
.footer-grid ul { list-style: none; padding: 0; margin: 0; }
.footer-grid li { font-size: 13px; margin-bottom: 8px; }
.footer-grid a { color: var(--crt-white); }
.footer-grid a:hover { color: var(--revv-cyan); }
.footer-bottom {
  border-top: 1px solid var(--gridline-gray);
  padding-top: 16px;
  font-size: 11px;
  font-family: var(--font-mono);
  color: var(--gridline-gray);
  display: flex;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 12px;
}

/* ============= PRODUCT — PAGE HEADER ============= */
.page-header {
  position: relative;
  background: var(--lot-black);
  padding: 80px 64px;
  overflow: hidden;
}
.page-header.car-pattern::before {
  content: '';
  position: absolute; inset: 0;
  background-image: url("assets/car-tile.svg");
  background-size: 80px 60px;
  background-repeat: repeat;
  opacity: 0.18;
  pointer-events: none;
}
.page-header h1 {
  font-family: var(--font-pixel);
  font-size: 36px;
  color: var(--crt-white);
  margin-top: 16px;
  line-height: 1.4;
}
.page-header .ph-sub {
  margin-top: 20px;
  font-size: 15px;
  color: var(--crt-white);
  opacity: 0.85;
  max-width: 520px;
}
.page-header.checker-bottom { padding-bottom: 80px; }

/* ============= PRODUCT — FILTER PANEL ============= */
.filter-section {
  background: var(--screen-fog);
  padding: 48px 64px;
}
.filter-frame {
  border: 2px solid var(--revv-cyan);
  background: var(--lot-black);
  margin-top: 20px;
}
.filter-frame .browser-bar {
  background: var(--gridline-gray);
  height: 24px;
  padding: 0 12px;
  display: flex; align-items: center; gap: 12px;
  border-bottom: 2px solid var(--revv-cyan);
  position: relative;
}
.filter-frame .browser-url {
  flex: none;
  background: transparent;
  border: none;
  color: var(--crt-white);
  font-size: 11px;
  position: absolute;
  left: 50%;
  transform: translateX(-50%);
}
.filter-frame .filter-body {
  padding: 32px;
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 16px;
}
.filter-field label {
  display: block;
  font-family: var(--font-accent);
  font-size: 10px;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--crt-white);
  margin-bottom: 8px;
}
.filter-field input[type=text] {
  width: 100%;
  background: var(--lot-black);
  border: 2px solid var(--revv-cyan);
  color: var(--crt-white);
  font-family: var(--font-mono);
  font-size: 14px;
  padding: 10px 12px;
}
.filter-field input::placeholder { color: var(--gridline-gray); }
.range-bar {
  width: 100%;
  height: 12px;
  background: var(--gridline-gray);
  position: relative;
  margin-top: 6px;
}
.range-bar .fill {
  position: absolute;
  top: 0; height: 12px;
  background: var(--revv-cyan);
  left: 20%; right: 30%;
}
.range-bar.purple .fill { background: var(--turbo-purple); }
.range-bar .thumb {
  position: absolute;
  top: -2px;
  width: 12px; height: 16px;
  background: var(--nitro-lime);
}
.range-bar .thumb.left { left: calc(20% - 6px); }
.range-bar .thumb.right { right: calc(30% - 6px); }
.range-meta {
  display: flex;
  justify-content: space-between;
  margin-top: 8px;
  font-size: 12px;
  color: var(--crt-white);
}
.chips { display: flex; flex-wrap: wrap; gap: 6px; }
.chip {
  font-family: var(--font-accent);
  text-transform: uppercase;
  letter-spacing: 0.12em;
  font-size: 10px;
  background: var(--gridline-gray);
  border: 2px solid var(--gridline-gray);
  color: var(--crt-white);
  padding: 6px 10px;
  cursor: pointer;
}
.chip.active {
  border-color: var(--revv-cyan);
  color: var(--revv-cyan);
  background: var(--lot-black);
}
.filter-search-btn {
  display: block;
  width: calc(100% - 64px);
  margin: 0 32px 32px;
  background: var(--revv-cyan);
  color: var(--lot-black);
  font-family: var(--font-accent);
  font-size: 12px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  border: 2px solid var(--lot-black);
  padding: 16px;
  cursor: pointer;
}

/* ============= PRODUCT — LISTINGS ============= */
.signature-section {
  position: relative;
  background: var(--lot-black);
  padding: 72px 0 64px;
  overflow: hidden;
}
.signature-section .container { padding: 0 64px; }
.signature-headline {
  font-family: var(--font-pixel);
  font-size: 64px;
  color: var(--revv-cyan);
  text-transform: uppercase;
  white-space: nowrap;
  margin-top: 12px;
  line-height: 1.1;
}
.signature-rule {
  height: 4px;
  width: 100%;
  background: var(--turbo-purple);
  margin-top: 16px;
}
.signature-sub {
  margin-top: 20px;
  font-size: 14px;
  color: var(--crt-white);
  opacity: 0.7;
}
.listing-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 20px 16px;
  margin-top: 40px;
}
.listing-card {
  position: relative;
  background: var(--screen-fog);
  border: 2px solid var(--revv-cyan);
  padding: 24px 20px 16px;
  display: flex;
  flex-direction: column;
}
.listing-badge {
  position: absolute;
  top: -10px; left: -10px;
  font-family: var(--font-accent);
  font-size: 9px;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  padding: 6px 10px;
  border: 2px solid var(--lot-black);
  z-index: 2;
}
.badge-best { background: var(--nitro-lime); color: var(--lot-black); }
.badge-pop { background: var(--revv-cyan); color: var(--lot-black); }
.badge-fast { background: var(--pixel-magenta); color: var(--crt-white); }
.badge-low { background: var(--turbo-purple); color: var(--crt-white); }
.badge-lux { background: var(--gridline-gray); color: var(--crt-white); }
.badge-ev { background: var(--pixel-magenta); color: var(--crt-white); }
.listing-title {
  font-family: var(--font-pixel);
  font-size: 13px;
  color: var(--crt-white);
  line-height: 1.5;
}
.listing-price {
  display: inline-block;
  margin-top: 8px;
  font-family: var(--font-pixel);
  font-size: 13px;
  color: var(--nitro-lime);
}
.listing-spec {
  font-family: var(--font-mono);
  font-size: 12px;
  color: var(--crt-white);
  opacity: 0.85;
  margin-top: 8px;
}
.listing-status {
  display: flex; align-items: center; gap: 8px;
  margin-top: 6px;
  font-family: var(--font-mono);
  font-size: 11px;
  color: var(--crt-white);
}
.listing-status::before {
  content: '';
  width: 8px; height: 8px;
  background: var(--nitro-lime);
  border-radius: 50%;
}
.listing-loc {
  display: inline-block;
  margin-top: 10px;
  font-family: var(--font-accent);
  font-size: 10px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  background: var(--gridline-gray);
  color: var(--crt-white);
  padding: 4px 8px;
  align-self: flex-start;
}
.listing-divider {
  border: 0;
  border-top: 1px solid var(--gridline-gray);
  margin: 12px 0;
}
.listing-cta-row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px;
}
.listing-btn {
  font-family: var(--font-accent);
  text-transform: uppercase;
  letter-spacing: 0.12em;
  font-size: 10px;
  text-align: center;
  padding: 10px 6px;
  border: 2px solid var(--revv-cyan);
  background: transparent;
  color: var(--revv-cyan);
  text-decoration: none;
  cursor: pointer;
}
.listing-btn.primary { background: var(--revv-cyan); color: var(--lot-black); }

/* ============= COMPARISON ============= */
.compare-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  margin-top: 40px;
}
.compare-panel {
  background: var(--screen-fog);
  border: 2px solid var(--turbo-purple);
}
.compare-panel + .compare-panel { border-left: 0; }
.compare-header {
  background: var(--turbo-purple);
  height: 40px;
  display: flex; align-items: center; justify-content: center;
  font-family: var(--font-pixel);
  font-size: 14px;
  color: var(--lot-black);
}
.compare-body { padding: 32px; }
.compare-body p { font-size: 15px; }
.compare-metric {
  display: flex; justify-content: space-between; align-items: baseline;
  padding: 12px 0;
  border-bottom: 1px solid var(--gridline-gray);
}
.compare-metric:last-of-type { border-bottom: none; }
.compare-metric .label {
  font-family: var(--font-accent);
  font-size: 10px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}
.compare-metric .value {
  font-family: var(--font-mono);
  font-size: 20px;
  color: var(--nitro-lime);
}
.compare-cta { margin-top: 28px; }
.compare-cta .listing-btn { display: block; width: 100%; }

/* ============= PURPLE CTA ============= */
.cta-block {
  background: var(--turbo-purple);
  text-align: center;
  padding: 96px 48px;
  position: relative;
}
.cta-block h2 {
  font-family: var(--font-pixel);
  color: var(--lot-black);
  font-size: 28px;
  max-width: 720px;
  margin: 12px auto 0;
}
.cta-block p {
  color: var(--lot-black);
  opacity: 0.85;
  max-width: 560px;
  margin: 20px auto 0;
  font-size: 15px;
}
.cta-block .btn-row { justify-content: center; }

/* ============= SPECS PAGE ============= */
.specs-header {
  background: var(--lot-black);
  position: relative;
  padding: 80px 64px 64px;
  border-top: 3px solid var(--turbo-purple);
}
.specs-header::before {
  content: '';
  position: absolute; inset: 0;
  background-image:
    linear-gradient(45deg, var(--gridline-gray) 25%, transparent 25%, transparent 75%, var(--gridline-gray) 75%),
    linear-gradient(45deg, var(--gridline-gray) 25%, transparent 25%, transparent 75%, var(--gridline-gray) 75%);
  background-size: 24px 24px;
  background-position: 0 0, 12px 12px;
  opacity: 0.30;
  pointer-events: none;
}
.specs-header-grid {
  position: relative;
  z-index: 2;
  display: grid;
  grid-template-columns: 7fr 5fr;
  gap: 48px;
  align-items: start;
}
.spec-h1 {
  font-family: var(--font-pixel);
  font-size: 32px;
  color: var(--revv-cyan);
  margin-top: 16px;
  line-height: 1.4;
}
.spec-status {
  margin-top: 24px;
  font-family: var(--font-mono);
  font-size: 14px;
  color: var(--crt-white);
}
.spec-status .sep { color: var(--nitro-lime); padding: 0 6px; }
.spec-cta-stack {
  display: flex; flex-direction: column; gap: 12px;
  margin-top: 32px; align-items: flex-start;
}
.dash-mockup {
  border: 4px solid var(--turbo-purple);
  background: var(--screen-fog);
  box-shadow: 0 0 16px rgba(0,245,255,0.35);
}
.dash-mockup .browser-bar {
  background: var(--gridline-gray);
  border-bottom: 2px solid var(--turbo-purple);
}
.dash-body {
  padding: 24px;
  position: relative;
}
.dash-make {
  font-family: var(--font-pixel);
  font-size: 14px;
  color: var(--revv-cyan);
}
.dash-grade {
  position: absolute;
  top: 16px; right: 16px;
  background: var(--nitro-lime);
  color: var(--lot-black);
  font-family: var(--font-accent);
  font-size: 10px;
  letter-spacing: 0.12em;
  padding: 4px 8px;
  border: 2px solid var(--lot-black);
}
.dash-list { margin-top: 16px; }
.dash-row {
  display: flex; justify-content: space-between;
  padding: 6px 0;
  border-bottom: 1px dashed var(--gridline-gray);
  font-family: var(--font-mono);
  font-size: 12px;
}
.dash-row .k { color: var(--crt-white); opacity: 0.7; }
.dash-row .v { color: var(--crt-white); }
.dash-row.lime .v { color: var(--nitro-lime); }

/* Specs grid */
.specs-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 16px;
  margin-top: 32px;
}
.spec-cell {
  background: var(--lot-black);
  border: 2px solid var(--turbo-purple);
  padding: 28px 20px 20px;
  position: relative;
  transition: border-color 0.15s linear, box-shadow 0.15s linear;
}
.spec-cell:hover { border-color: var(--revv-cyan); box-shadow: 0 0 8px rgba(0,245,255,0.3); }
.spec-cell .cat-badge {
  position: absolute;
  top: 8px; left: 8px;
  font-family: var(--font-accent);
  font-size: 9px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--turbo-purple);
}
.spec-cell h3 {
  font-family: var(--font-accent);
  font-size: 12px;
  letter-spacing: 0.12em;
  color: var(--revv-cyan);
  text-transform: uppercase;
}
.spec-cell p {
  font-family: var(--font-mono);
  font-size: 14px;
  color: var(--crt-white);
  margin-top: 8px;
  line-height: 1.6;
}

/* Inspection / VERIFIED */
.verified-section {
  position: relative;
  background: var(--lot-black);
  padding: 96px 64px;
  overflow: hidden;
  text-align: center;
}
.verified-stamp {
  position: absolute;
  font-family: var(--font-pixel);
  font-size: 120px;
  color: var(--nitro-lime);
  opacity: 0.18;
  white-space: nowrap;
  top: 50%; left: 50%;
  transform: translate(-50%, -50%) rotate(-15deg);
  pointer-events: none;
  z-index: 1;
}
.verified-section .container { position: relative; z-index: 2; }
.verified-cards {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 20px;
  margin-top: 48px;
  position: relative;
  z-index: 2;
}
.vcard {
  background: var(--screen-fog);
  border: 3px solid var(--nitro-lime);
  padding: 32px 24px;
  text-align: left;
}
.vcard .system {
  font-family: var(--font-accent);
  font-size: 9px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--turbo-purple);
}
.vcard .num {
  font-family: var(--font-pixel);
  font-size: 22px;
  color: var(--nitro-lime);
  margin-top: 12px;
  line-height: 1.2;
}
.vcard .desc {
  margin-top: 12px;
  font-family: var(--font-mono);
  font-size: 13px;
  color: var(--crt-white);
  line-height: 1.6;
}

.inspect-chart {
  margin: 40px auto 0;
  max-width: 800px;
  background: var(--screen-fog);
  border: 2px solid var(--turbo-purple);
  padding: 24px;
  position: relative;
  z-index: 2;
}
.chart-row {
  display: grid;
  grid-template-columns: 110px 1fr 36px;
  gap: 12px;
  align-items: center;
  margin-bottom: 8px;
  font-family: var(--font-mono);
  font-size: 12px;
  color: var(--crt-white);
}
.chart-bar {
  position: relative;
  height: 14px;
  background: var(--turbo-purple);
}
.chart-bar .fill {
  position: absolute; left: 0; top: 0; bottom: 0;
  background: var(--revv-cyan);
}
.chart-row .num { text-align: right; color: var(--nitro-lime); }

/* Vehicle history timeline */
.history-section { background: var(--screen-fog); padding: 80px 64px; }
.history-grid {
  display: grid;
  grid-template-columns: 2fr 10fr;
  gap: 32px;
  margin-top: 32px;
  position: relative;
}
.history-rail {
  position: relative;
  border-right: 0;
  padding-right: 24px;
}
.history-rail::before {
  content: '';
  position: absolute;
  right: 0;
  top: 8px; bottom: 8px;
  width: 3px;
  background: var(--turbo-purple);
}
.history-events { padding-left: 32px; position: relative; }
.history-event {
  position: relative;
  padding: 8px 0 32px;
  border-bottom: 2px solid var(--gridline-gray);
  margin-bottom: 32px;
}
.history-event:last-child { border-bottom: none; margin-bottom: 0; }
.history-event::before {
  content: '';
  position: absolute;
  left: -45px; top: 14px;
  width: 16px; height: 16px;
  background: var(--nitro-lime);
}
.history-event.current::before {
  width: 24px; height: 24px;
  left: -49px; top: 10px;
  border: 2px solid var(--revv-cyan);
}
.history-event.current {
  background: var(--lot-black);
  border: 2px solid var(--revv-cyan);
  box-shadow: 0 0 12px rgba(0,245,255,0.25);
  padding: 16px;
}
.history-event h4 {
  font-family: var(--font-accent);
  font-size: 12px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--nitro-lime);
}
.history-event p {
  margin-top: 8px;
  font-family: var(--font-mono);
  font-size: 14px;
  color: var(--crt-white);
}
.history-sub {
  margin-top: 12px;
  font-family: var(--font-mono);
  font-size: 15px;
  color: var(--revv-cyan);
}
.history-sub-rule {
  height: 2px; background: var(--turbo-purple);
  width: 100%;
  margin-top: 24px; margin-bottom: 24px;
}

/* Magenta CTA close (specs) */
.magenta-cta {
  background: var(--pixel-magenta);
  text-align: center;
  padding: 96px 48px;
  position: relative;
}
.magenta-cta h2 {
  font-family: var(--font-pixel);
  font-size: 32px;
  color: var(--lot-black);
  max-width: 720px;
  margin: 12px auto 0;
  line-height: 1.4;
}
.magenta-cta p {
  color: var(--lot-black);
  opacity: 0.85;
  margin: 16px auto 0;
  max-width: 560px;
}
.magenta-cta .btn-row { justify-content: center; }
.magenta-cta .trust-line {
  margin-top: 28px;
  font-family: var(--font-mono);
  font-size: 12px;
  color: var(--lot-black);
  letter-spacing: 0.05em;
}
.magenta-cta .trust-line .star { color: var(--nitro-lime); }
.magenta-cta::before {
  content: '';
  position: absolute; inset: 0;
  background-image:
    linear-gradient(45deg, rgba(0,0,0,0.18) 25%, transparent 25%, transparent 75%, rgba(0,0,0,0.18) 75%),
    linear-gradient(45deg, rgba(0,0,0,0.18) 25%, transparent 25%, transparent 75%, rgba(0,0,0,0.18) 75%);
  background-size: 32px 32px;
  background-position: 0 0, 16px 16px;
  opacity: 0.3;
  pointer-events: none;
}

/* ============= GALLERY PAGE ============= */
.gallery-header {
  background: var(--lot-black);
  padding: 28px 64px;
  border-top: 0;
}
.gallery-header-grid {
  display: grid;
  grid-template-columns: 8fr 4fr;
  gap: 32px;
  align-items: center;
  margin-top: 8px;
}
.gallery-h1 {
  font-family: var(--font-pixel);
  font-size: 36px;
  color: var(--crt-white);
  line-height: 1.4;
  margin-top: 12px;
}
.gallery-h1 .magenta-dot { color: var(--pixel-magenta); }
.gallery-stat-strip {
  margin-top: 16px;
  font-family: var(--font-mono);
  font-size: 14px;
  color: var(--crt-white);
}
.gallery-stat-strip .sep { color: var(--revv-cyan); padding: 0 6px; }
.gallery-stat-strip .hot { color: var(--pixel-magenta); }
.gallery-cta-stack {
  display: flex; flex-direction: column; gap: 12px;
}
.gallery-cta-stack .btn { width: 100%; box-shadow: 0 0 8px rgba(0,245,255,0.4); }

/* Filmstrip */
.filmstrip-section {
  position: relative;
  background: var(--lot-black);
  padding: 40px 0 48px;
  overflow: hidden;
}
.filmstrip-section .filmstrip-header {
  padding: 0 64px;
  display: grid;
  grid-template-columns: 8fr 4fr;
  gap: 24px;
  align-items: start;
}
.exterior-watermark {
  position: absolute;
  font-family: var(--font-pixel);
  font-size: 96px;
  color: var(--turbo-purple);
  opacity: 0.15;
  top: 50%; left: 40px;
  transform: translateY(-30%);
  white-space: nowrap;
  pointer-events: none;
  z-index: 1;
}
.hotspot-diagram {
  background: var(--screen-fog);
  border: 2px solid var(--gridline-gray);
  padding: 16px;
  max-width: 320px;
  justify-self: end;
}
.filmstrip {
  display: flex; gap: 12px;
  margin-top: 24px;
  padding: 12px 0 12px 80px;
  overflow-x: auto;
  position: relative;
  z-index: 2;
}
.film-tile {
  flex: 0 0 340px;
  width: 340px;
  height: 260px;
  background: var(--screen-fog);
  border: 3px solid var(--revv-cyan);
  box-shadow: 0 0 10px rgba(0,245,255,0.5);
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
}
.film-tile:hover { box-shadow: 0 0 18px rgba(0,245,255,0.8); }
.film-tile .photo-placeholder {
  width: 80%; height: 70%;
  background:
    linear-gradient(135deg, var(--gridline-gray) 0%, var(--screen-fog) 100%);
  position: relative;
  border: 1px solid var(--gridline-gray);
  display: flex;
  align-items: center;
  justify-content: center;
}
.film-tile .photo-placeholder svg { width: 60%; height: 60%; opacity: 0.6; }
.film-tile .tile-overlay {
  position: absolute;
  bottom: 0; left: 0; right: 0;
  background: rgba(10,10,10,0.85);
  padding: 12px 16px;
  display: flex; justify-content: space-between; align-items: center;
}
.tile-overlay .ttitle {
  font-family: var(--font-accent);
  font-size: 10px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--crt-white);
}
.tile-overlay .pcount {
  background: var(--nitro-lime);
  color: var(--lot-black);
  font-family: var(--font-accent);
  font-size: 10px;
  letter-spacing: 0.12em;
  padding: 3px 8px;
}
.film-cap {
  font-family: var(--font-mono);
  font-size: 13px;
  color: var(--crt-white);
  opacity: 0.65;
  padding: 0 64px;
  margin-top: 12px;
  display: flex;
  gap: 12px;
}
.film-cap .item { flex: 0 0 340px; max-width: 340px; }

/* Interior tabs */
.interior-section {
  background: var(--screen-fog);
  padding: 56px 64px;
}
.tab-panel {
  margin-top: 32px;
  display: grid;
  grid-template-columns: 2fr 10fr;
  border: 2px solid var(--gridline-gray);
}
.tab-list {
  border-right: 1px solid var(--gridline-gray);
}
.tab {
  display: block;
  padding: 16px 16px;
  border-left: 2px solid var(--gridline-gray);
  border-bottom: 1px solid var(--gridline-gray);
  font-family: var(--font-accent);
  font-size: 10px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: rgba(232,240,242,0.5);
  background: transparent;
  text-decoration: none;
  cursor: pointer;
}
.tab.active {
  border-left: 4px solid var(--turbo-purple);
  background: rgba(204,0,255,0.08);
  color: var(--turbo-purple);
}
.tab:last-child { border-bottom: none; }
.tab-content { padding: 24px; }
.tab-meta {
  display: flex; align-items: center; gap: 12px;
}
.tab-meta .ctitle { font-family: var(--font-mono); font-size: 13px; color: var(--revv-cyan); }
.tab-meta .badge {
  background: var(--lot-black);
  color: var(--nitro-lime);
  font-family: var(--font-accent);
  font-size: 10px;
  letter-spacing: 0.12em;
  padding: 3px 7px;
  border: 1px solid var(--nitro-lime);
}
.tab-desc { margin-top: 8px; font-size: 14px; color: var(--crt-white); opacity: 0.8; max-width: 600px; }
.photo-2x2 {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 12px;
  margin-top: 16px;
}
.mini-photo {
  height: 165px;
  background: var(--screen-fog);
  border: 3px solid var(--revv-cyan);
  box-shadow: 0 0 8px rgba(0,245,255,0.4);
  position: relative;
  display: flex; align-items: center; justify-content: center;
}
.mini-photo .photo-placeholder {
  width: 80%; height: 70%;
  background: linear-gradient(135deg, var(--gridline-gray) 0%, var(--lot-black) 100%);
  display: flex; align-items: center; justify-content: center;
}
.mini-photo .tile-overlay {
  background: rgba(10,10,10,0.8);
  padding: 8px 12px;
  height: 30px;
  font-size: 10px;
}
.mini-photo .ttitle { color: var(--crt-white); }
.mini-photo .view { color: var(--revv-cyan); font-family: var(--font-accent); font-size: 10px; letter-spacing: 0.12em; }

/* Mechanical */
.mech-section { background: var(--lot-black); padding: 48px 64px 56px; }
.mech-grid {
  display: grid;
  grid-template-columns: 3fr 9fr;
  margin-top: 32px;
  border-top: 1px solid var(--gridline-gray);
}
.mech-index {
  border-right: 2px solid var(--gridline-gray);
}
.mech-row {
  display: flex; align-items: center; gap: 16px;
  padding: 0 16px;
  height: 100px;
  border-bottom: 1px solid var(--gridline-gray);
  border-left: 3px solid transparent;
  cursor: pointer;
}
.mech-row.active {
  border-left-color: var(--nitro-lime);
  background: rgba(46,46,68,0.4);
}
.mech-row:last-child { border-bottom: none; }
.mech-row .icon { width: 32px; height: 32px; color: var(--revv-cyan); flex: none; }
.mech-row .title {
  font-family: var(--font-accent);
  font-size: 11px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--crt-white);
  flex: 1;
}
.mech-row .pcount {
  background: var(--nitro-lime);
  color: var(--lot-black);
  font-family: var(--font-accent);
  font-size: 10px;
  letter-spacing: 0.12em;
  padding: 3px 7px;
}
.mech-photos {
  padding: 16px;
}
.mech-photo-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 12px;
}
.mech-photo {
  height: 165px;
  background: var(--screen-fog);
  border: 3px solid var(--revv-cyan);
  box-shadow: 0 0 8px rgba(0,245,255,0.4);
  display: flex; align-items: center; justify-content: center;
}
.mech-photo .photo-placeholder {
  width: 80%; height: 70%;
  background: linear-gradient(135deg, var(--gridline-gray) 0%, var(--lot-black) 100%);
  display: flex; align-items: center; justify-content: center;
}
.mech-photo svg { width: 60%; height: 60%; opacity: 0.6; }
.mech-condition {
  margin-top: 16px;
  padding-top: 16px;
  border-top: 1px solid var(--revv-cyan);
  font-size: 14px;
  color: var(--crt-white);
  opacity: 0.85;
  max-width: 600px;
}

/* Gallery CTA close (purple) */
.gallery-cta-close {
  background: var(--turbo-purple);
  position: relative;
  padding: 80px 48px;
  text-align: center;
}
.gallery-cta-close h2 {
  font-family: var(--font-pixel);
  font-size: 36px;
  margin: 16px auto 0;
  max-width: 780px;
  color: var(--crt-white);
  line-height: 1.4;
}
.gallery-cta-close .line1 { color: var(--nitro-lime); display: block; }
.gallery-cta-close .strikeword { color: var(--nitro-lime); position: relative; display: inline-block; }
.gallery-cta-close .strikeword::after {
  content: '';
  position: absolute; left: 0; right: 0; top: 50%;
  height: 4px; background: var(--pixel-magenta);
}
.gallery-cta-close p {
  margin: 28px auto 0;
  max-width: 560px;
  font-size: 16px;
  color: var(--crt-white);
  opacity: 0.85;
}
.gallery-cta-close .btn-row { margin-top: 32px; justify-content: center; }
.gallery-cta-close .btn-primary-lime {
  background: var(--nitro-lime);
  border-color: var(--lot-black);
  color: var(--lot-black);
  min-width: 340px;
}
.gallery-cta-close .btn-primary-lime:hover { background: var(--crt-white); }
.gallery-cta-close .btn-out-white {
  background: transparent;
  border-color: var(--crt-white);
  color: var(--crt-white);
}
.gallery-cta-close .btn-out-white:hover { background: var(--nitro-lime); border-color: var(--nitro-lime); color: var(--lot-black); }

/* ============= RESERVE PAGE ============= */
.reserve-header {
  position: relative;
  background: var(--lot-black);
  padding: 64px 64px 80px;
  overflow: hidden;
  min-height: 480px;
}
.reserve-stamp {
  position: absolute;
  font-family: var(--font-pixel);
  font-size: 80px;
  color: var(--turbo-purple);
  opacity: 0.18;
  top: 50%; left: 50%;
  transform: translate(-50%,-50%) rotate(-8deg);
  white-space: nowrap;
  pointer-events: none;
  z-index: 1;
}
.reserve-grid {
  position: relative; z-index: 2;
  display: grid;
  grid-template-columns: 7fr 5fr;
  gap: 32px;
  align-items: end;
}
.reserve-h1 {
  font-family: var(--font-pixel);
  font-size: 40px;
  color: var(--crt-white);
  line-height: 1.2;
  margin-top: 16px;
}
.reserve-sub {
  margin-top: 24px;
  font-family: var(--font-mono);
  font-size: 17px;
  line-height: 1.75;
  color: var(--crt-white);
  opacity: 0.85;
  max-width: 520px;
}
.reserve-illo { align-self: end; }

/* Story block */
.story-section {
  background: var(--lot-black);
  padding: 48px 64px;
}
.story-frame {
  max-width: 860px;
  margin: 0 auto;
  border: 2px solid var(--revv-cyan);
  background: var(--screen-fog);
}
.story-bar {
  height: 36px;
  background: var(--gridline-gray);
  display: flex; align-items: center; gap: 8px;
  padding: 0 14px;
  border-bottom: 2px solid var(--revv-cyan);
}
.story-bar .browser-dot { width: 10px; height: 10px; border-radius: 50%; }
.story-body { padding: 32px; }
.story-body h2 {
  font-family: var(--font-pixel);
  font-size: 22px;
  margin-top: 12px;
  color: var(--crt-white);
  line-height: 1.4;
}
.story-specs {
  margin-top: 16px;
  font-family: var(--font-mono);
  font-size: 15px;
  color: var(--nitro-lime);
  display: flex; flex-wrap: wrap; align-items: center; gap: 12px;
}
.story-badge {
  font-family: var(--font-accent);
  font-size: 10px;
  letter-spacing: 0.12em;
  background: var(--nitro-lime);
  color: var(--lot-black);
  border: 4px solid var(--lot-black);
  padding: 4px 8px;
}
.story-body .body-copy {
  margin-top: 20px;
  font-size: 15px;
  color: var(--crt-white);
  opacity: 0.85;
  max-width: 640px;
}
.story-table {
  margin-top: 28px;
  border-top: 2px solid var(--revv-cyan);
  border-bottom: 2px solid var(--revv-cyan);
}
.story-row {
  display: flex; justify-content: space-between; align-items: baseline;
  padding: 12px 0;
  border-bottom: 1px dashed var(--gridline-gray);
}
.story-row:last-child { border-bottom: none; }
.story-row .lbl {
  font-family: var(--font-mono);
  font-weight: 700;
  font-size: 14px;
  color: var(--crt-white);
}
.story-row .val { font-family: var(--font-mono); font-size: 14px; color: var(--crt-white); }
.story-row.hold .val { color: var(--pixel-magenta); font-weight: 700; }
.story-row.total .val { color: var(--nitro-lime); }

/* Form section */
.form-section {
  background: var(--screen-fog);
  padding: 64px;
}
.form-grid {
  display: grid;
  grid-template-columns: 7fr 5fr;
  gap: 32px;
}
.step-chip {
  display: inline-block;
  font-family: var(--font-accent);
  font-size: 10px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--gridline-gray);
  background: var(--revv-cyan);
  border: 2px solid var(--revv-cyan);
  padding: 4px 10px;
  margin-bottom: 12px;
}
.form-list { display: grid; gap: 20px; margin-top: 28px; }
.form-field label {
  display: block;
  font-family: var(--font-accent);
  font-size: 10px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--crt-white);
  margin-bottom: 8px;
}
.form-field input, .form-field select {
  width: 100%;
  background: var(--lot-black);
  color: var(--crt-white);
  font-family: var(--font-mono);
  font-size: 15px;
  padding: 14px;
  border: 2px solid var(--gridline-gray);
  outline: none;
}
.form-field input:focus, .form-field select:focus { border-color: var(--revv-cyan); }
.form-field .desc {
  margin-top: 6px;
  font-family: var(--font-mono);
  font-size: 13px;
  color: var(--gridline-gray);
}
.radio-group { display: flex; flex-direction: column; gap: 8px; }
.radio-group label {
  display: flex; align-items: center; gap: 10px;
  font-family: var(--font-mono);
  font-size: 14px;
  color: var(--crt-white);
  text-transform: none;
  letter-spacing: 0;
  cursor: pointer;
}
.radio-square {
  display: inline-block;
  width: 14px; height: 14px;
  background: var(--lot-black);
  border: 2px solid var(--revv-cyan);
  flex: none;
}
.form-cta {
  margin-top: 32px;
  display: block;
  width: 100%;
  background: var(--revv-cyan);
  color: var(--lot-black);
  font-family: var(--font-accent);
  font-size: 12px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  border: 2px solid var(--revv-cyan);
  padding: 16px;
  cursor: pointer;
  text-align: center;
}
.form-cta:hover { background: var(--nitro-lime); border-color: var(--nitro-lime); }

.trust-sidebar {
  background: var(--screen-fog);
  border: 2px solid var(--turbo-purple);
  padding: 32px;
}
.trust-sidebar .eyebrow { color: var(--turbo-purple); }
.trust-sidebar ul {
  list-style: none; padding: 0; margin: 16px 0 24px;
  display: flex; flex-direction: column; gap: 12px;
}
.trust-sidebar li {
  font-family: var(--font-mono);
  font-size: 14px;
  color: var(--crt-white);
  display: flex; gap: 10px;
}
.trust-check {
  width: 16px; height: 16px;
  background: var(--nitro-lime);
  flex: none;
  display: inline-block;
  position: relative;
}
.trust-check::after {
  content: '';
  position: absolute;
  left: 4px; top: 1px;
  width: 4px; height: 8px;
  border: solid var(--lot-black);
  border-width: 0 2px 2px 0;
  transform: rotate(45deg);
}
.secure-badge {
  font-family: var(--font-accent);
  font-size: 10px;
  letter-spacing: 0.12em;
  background: var(--pixel-magenta);
  color: var(--crt-white);
  padding: 6px 10px;
  display: inline-flex;
  gap: 6px; align-items: center;
}
.padlock-mini {
  width: 12px; height: 14px;
  border: 2px solid var(--crt-white);
  position: relative;
}
.padlock-mini::before {
  content: '';
  position: absolute;
  width: 6px; height: 5px;
  border: 2px solid var(--crt-white);
  border-bottom: 0;
  top: -5px; left: 1px;
}

/* Guarantee grid (Reserve s4) */
.guarantee-section {
  background: var(--turbo-purple);
  padding: 72px 48px;
  text-align: center;
}
.guarantee-section .eyebrow { color: var(--lot-black); }
.guarantee-section .eyebrow::before { background: var(--lot-black); }
.guarantee-section h2 {
  font-family: var(--font-pixel);
  font-size: 28px;
  color: var(--lot-black);
  margin-top: 16px;
}
.guarantee-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 16px;
  max-width: 1000px;
  margin: 40px auto 0;
}
.gcard {
  background: var(--screen-fog);
  border: 2px solid var(--lot-black);
  padding: 24px;
  text-align: center;
}
.gcard .icon { width: 40px; height: 40px; margin: 0 auto; color: var(--revv-cyan); }
.gcard.alt .icon { color: var(--nitro-lime); }
.gcard h3 {
  font-family: var(--font-pixel);
  font-size: 12px;
  color: var(--crt-white);
  margin-top: 12px;
  line-height: 1.5;
}
.gcard p {
  margin-top: 10px;
  font-size: 14px;
  color: var(--crt-white);
  opacity: 0.85;
  line-height: 1.6;
}

/* FAQ */
.faq-section {
  background: var(--lot-black);
  padding: 80px 64px 0;
}
.faq-wrap {
  max-width: 760px;
  margin: 0 auto;
  text-align: center;
}
.faq-wrap h2 {
  font-family: var(--font-pixel);
  font-size: 20px;
  color: var(--crt-white);
  margin-top: 20px;
  line-height: 1.6;
}
.faq-wrap h2 .cyan { color: var(--revv-cyan); }
.faq-list {
  margin: 32px 0 0;
  border-top: 1px solid var(--gridline-gray);
  border-bottom: 1px solid var(--gridline-gray);
  text-align: left;
}
.faq-row {
  border-bottom: 1px solid var(--gridline-gray);
  padding: 0;
}
.faq-row:last-child { border-bottom: none; }
.faq-q {
  display: flex; align-items: center; justify-content: space-between;
  padding: 18px 16px;
  cursor: pointer;
  font-family: var(--font-mono);
  font-weight: 700;
  font-size: 16px;
  color: var(--crt-white);
}
.faq-q .toggle {
  font-family: var(--font-mono);
  color: var(--revv-cyan);
  font-size: 18px;
}
.faq-row[open] .faq-q .toggle::before { content: '−'; }
.faq-row .faq-q .toggle::before { content: '+'; }
.faq-row[open] {
  background: var(--screen-fog);
  border-left: 4px solid var(--revv-cyan);
}
.faq-a {
  padding: 0 16px 16px;
  font-family: var(--font-mono);
  font-size: 15px;
  color: var(--crt-white);
  opacity: 0.85;
  line-height: 1.75;
}

.faq-cta-strip {
  background: var(--revv-cyan);
  padding: 32px 16px;
  display: flex;
  align-items: center;
  justify-content: center;
}
.faq-cta-strip .btn {
  background: var(--lot-black);
  color: var(--crt-white);
  border-color: var(--lot-black);
  min-width: 280px;
  text-align: center;
  display: flex; align-items: center; justify-content: center; gap: 8px;
  box-shadow: none;
}
.faq-cta-strip .btn:hover { background: var(--nitro-lime); color: var(--lot-black); border-color: var(--lot-black); }
.faq-cta-strip .check {
  display: inline-block;
  width: 14px; height: 14px;
  background: var(--nitro-lime);
  position: relative;
}
.faq-cta-strip .check::after {
  content: '';
  position: absolute;
  left: 4px; top: 1px;
  width: 4px; height: 8px;
  border: solid var(--lot-black);
  border-width: 0 2px 2px 0;
  transform: rotate(45deg);
}

/* ============= UTILITIES ============= */
.text-center { text-align: center; }
.flex-row { display: flex; gap: 16px; flex-wrap: wrap; }

/* ============= RESPONSIVE ============= */
@media (max-width: 1100px) {
  .container, .nav, .filter-section, .form-section, .specs-header,
  .verified-section, .history-section, .mech-section, .interior-section,
  .filmstrip-section .filmstrip-header, .filmstrip, .gallery-header,
  .story-section, .reserve-header, .signature-section .container, .page-header,
  section { padding-left: 32px; padding-right: 32px; }
  .hero-headline { font-size: 56px; }
  .signature-headline { font-size: 48px; }
  .stats-grid { grid-template-columns: repeat(2, 1fr); }
  .stat-card:nth-child(2) { border-right: none; }
  .feature-block { grid-template-columns: 1fr; }
  .feature-text { border-right: none; padding-right: 0; }
  .feature-grid { padding-left: 0; margin-top: 24px; }
  .timeline-row { grid-template-columns: repeat(2, 1fr); }
  .testimonials-stack { grid-template-columns: 1fr; }
  .tcard-1, .tcard-2, .tcard-3 { transform: none; margin-top: 24px; }
  .listing-grid { grid-template-columns: repeat(2, 1fr); }
  .compare-grid { grid-template-columns: 1fr; }
  .specs-header-grid, .gallery-header-grid, .reserve-grid { grid-template-columns: 1fr; }
  .specs-grid { grid-template-columns: 1fr 1fr; }
  .verified-cards { grid-template-columns: 1fr 1fr; }
  .history-grid { grid-template-columns: 1fr; }
  .history-rail { display: none; }
  .form-grid { grid-template-columns: 1fr; }
  .guarantee-grid { grid-template-columns: 1fr 1fr; }
  .filter-frame .filter-body { grid-template-columns: 1fr 1fr; }
  .footer-grid { grid-template-columns: 1fr 1fr; }
  .filmstrip-section .filmstrip-header { grid-template-columns: 1fr; }
  .hotspot-diagram { justify-self: start; }
  .tab-panel { grid-template-columns: 1fr; }
  .mech-grid { grid-template-columns: 1fr; }
  .mech-photo-grid { grid-template-columns: repeat(2, 1fr); }
}
@media (max-width: 720px) {
  .nav { flex-wrap: wrap; gap: 12px; padding: 12px 16px; }
  .nav-links { gap: 16px; flex-wrap: wrap; }
  section { padding: 56px 20px; }
  .container, .page-header, .signature-section .container, .filter-section,
  .specs-header, .verified-section, .history-section, .mech-section,
  .interior-section, .filmstrip-section .filmstrip-header, .gallery-header,
  .story-section, .form-section, .reserve-header, .hero { padding-left: 20px; padding-right: 20px; }
  .hero-headline { font-size: 36px; }
  .signature-headline { font-size: 28px; }
  .stats-grid { grid-template-columns: 1fr 1fr; }
  .stat-num { font-size: 36px; }
  .listing-grid { grid-template-columns: 1fr; }
  .specs-grid, .verified-cards, .guarantee-grid { grid-template-columns: 1fr; }
  .timeline-row { grid-template-columns: 1fr; gap: 32px; }
  .timeline-row::before { display: none; }
  .filter-frame .filter-body { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: 1fr; }
  .reserve-h1 { font-size: 26px; }
  .magenta-cta h2, .gallery-cta-close h2 { font-size: 22px; }
  .mech-photo-grid { grid-template-columns: 1fr; }
  .photo-2x2 { grid-template-columns: 1fr; }
  .verified-stamp { font-size: 64px; }
  .reserve-stamp { font-size: 48px; }
  .exterior-watermark { font-size: 48px; }
}

tool_use_result.content:
/* RevvLot — Retro 90s Web Used Car Marketplace */
@import url('https://fonts.googleapis.com/css2?family=Press+Start+2P&family=IBM+Plex+Mono:wght@400;500;700&family=Archivo+Black&family=Archivo:wght@800&display=swap');

:root {
  --lot-black: #0A0A0A;
  --revv-cyan: #00F5FF;
  --turbo-purple: #CC00FF;
  --nitro-lime: #AAFF00;
  --screen-fog: #1C1C2E;
  --pixel-magenta: #FF2D78;
  --crt-white: #E8F0F2;
  --gridline-gray: #2E2E44;

  --font-pixel: 'Press Start 2P', monospace;
  --font-mono: 'IBM Plex Mono', monospace;
  --font-accent: 'Archivo Black', 'Archivo', sans-serif;
}

* { box-sizing: border-box; }
html, body {
  margin: 0; padding: 0;
  background: var(--lot-black);
  color: var(--crt-white);
  font-family: var(--font-mono);
  font-size: 16px;
  line-height: 1.75;
  overflow-x: hidden;
}

a { color: var(--revv-cyan); text-decoration: none; }
a:hover { text-decoration: underline; }

img, svg { display: block; max-width: 100%; }

h1, h2, h3, h4 {
  font-family: var(--font-pixel);
  text-transform: uppercase;
  margin: 0;
  line-height: 1.4;
}

p { margin: 0; }

/* ============= LAYOUT ============= */
.container {
  width: 100%;
  max-width: 1280px;
  margin: 0 auto;
  padding: 0 64px;
}

.full-bleed { width: 100%; }

.eyebrow {
  font-family: var(--font-accent);
  text-transform: uppercase;
  letter-spacing: 0.12em;
  font-size: 11px;
  color: var(--revv-cyan);
  display: inline-flex;
  align-items: center;
  gap: 12px;
  margin: 0;
}
.eyebrow::before {
  content: '';
  display: inline-block;
  width: 32px; height: 2px;
  background: currentColor;
}
.eyebrow.no-bar::before { display: none; }
.eyebrow.lime { color: var(--nitro-lime); }
.eyebrow.purple { color: var(--turbo-purple); }
.eyebrow.magenta { color: var(--pixel-magenta); }
.eyebrow.dark { color: var(--lot-black); }

/* ============= NAV ============= */
.nav {
  background: var(--lot-black);
  border-bottom: 2px solid var(--turbo-purple);
  padding: 14px 64px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  position: sticky;
  top: 0;
  z-index: 100;
}
.nav-logo {
  font-family: var(--font-pixel);
  color: var(--revv-cyan);
  font-size: 18px;
  letter-spacing: 1px;
  display: flex;
  align-items: center;
  gap: 10px;
  text-decoration: none;
}
.nav-logo .pixel-spark {
  width: 14px; height: 14px;
  background: var(--nitro-lime);
  box-shadow:
    -7px 0 0 var(--pixel-magenta),
    7px 0 0 var(--turbo-purple);
}
.nav-links {
  display: flex; gap: 28px;
  list-style: none;
  margin: 0; padding: 0;
}
.nav-links a {
  font-family: var(--font-accent);
  text-transform: uppercase;
  letter-spacing: 0.12em;
  font-size: 11px;
  color: var(--crt-white);
  text-decoration: none;
}
.nav-links a:hover, .nav-links a.active { color: var(--revv-cyan); text-decoration: none; }
.nav-cta {
  font-family: var(--font-accent);
  text-transform: uppercase;
  letter-spacing: 0.12em;
  font-size: 10px;
  background: var(--revv-cyan);
  color: var(--lot-black);
  padding: 10px 16px;
  border: 2px solid var(--revv-cyan);
  box-shadow: 4px 4px 0 var(--lot-black);
}

/* ============= BUTTONS ============= */
.btn {
  display: inline-block;
  font-family: var(--font-accent);
  text-transform: uppercase;
  letter-spacing: 0.12em;
  font-size: 11px;
  padding: 14px 28px;
  border: 3px solid var(--revv-cyan);
  background: var(--revv-cyan);
  color: var(--lot-black);
  cursor: pointer;
  text-decoration: none;
  box-shadow: 4px 4px 0 var(--lot-black);
  transition: transform 0.08s linear, box-shadow 0.08s linear;
}
.btn:hover { transform: translate(2px,2px); box-shadow: 2px 2px 0 var(--lot-black); text-decoration: none; }
.btn-secondary {
  background: transparent;
  border-color: var(--crt-white);
  color: var(--crt-white);
  box-shadow: 4px 4px 0 var(--gridline-gray);
}
.btn-secondary:hover { box-shadow: 2px 2px 0 var(--gridline-gray); }
.btn-purple {
  background: var(--turbo-purple);
  border-color: var(--turbo-purple);
  color: var(--crt-white);
}
.btn-magenta {
  background: var(--pixel-magenta);
  border-color: var(--pixel-magenta);
  color: var(--crt-white);
}
.btn-lime {
  background: var(--nitro-lime);
  border-color: var(--lot-black);
  color: var(--lot-black);
}
.btn-outline {
  background: transparent;
  border-color: var(--revv-cyan);
  color: var(--revv-cyan);
  box-shadow: 4px 4px 0 var(--gridline-gray);
}
.btn-outline:hover { background: var(--revv-cyan); color: var(--lot-black); }
.btn-dark-on-purple {
  background: var(--lot-black);
  border-color: var(--lot-black);
  color: var(--crt-white);
}
.btn-dark-on-purple:hover { background: var(--revv-cyan); color: var(--lot-black); }

.btn-row {
  display: flex; gap: 16px; flex-wrap: wrap;
  margin-top: 32px;
}

/* ============= STRUCTURAL DIVIDERS ============= */
.purple-rule {
  height: 8px;
  width: 100%;
  background:
    repeating-linear-gradient(
      90deg,
      var(--turbo-purple) 0 8px,
      var(--turbo-purple) 8px 16px
    );
}
.checker-strip {
  height: 16px;
  width: 100%;
  background-image:
    linear-gradient(45deg, var(--nitro-lime) 25%, transparent 25%, transparent 75%, var(--nitro-lime) 75%),
    linear-gradient(45deg, var(--nitro-lime) 25%, var(--lot-black) 25%, var(--lot-black) 75%, var(--nitro-lime) 75%);
  background-size: 16px 16px;
  background-position: 0 0, 8px 8px;
}
.checker-strip.gray {
  background-image:
    linear-gradient(45deg, var(--gridline-gray) 25%, transparent 25%, transparent 75%, var(--gridline-gray) 75%),
    linear-gradient(45deg, var(--gridline-gray) 25%, var(--lot-black) 25%, var(--lot-black) 75%, var(--gridline-gray) 75%);
}

/* ============= SECTION DEFAULTS ============= */
section {
  position: relative;
  padding: 80px 64px;
}
section.tight { padding: 48px 64px; }
section.huge { padding: 96px 64px; }
section.dark { background: var(--lot-black); }
section.fog { background: var(--screen-fog); }
section.purple { background: var(--turbo-purple); }
section.magenta { background: var(--pixel-magenta); }

.section-title {
  font-family: var(--font-pixel);
  font-size: 26px;
  color: var(--crt-white);
  margin: 16px 0 0;
  line-height: 1.4;
}
.section-title.cyan { color: var(--revv-cyan); }
.section-title.dark { color: var(--lot-black); }

.section-sub {
  margin-top: 16px;
  color: var(--crt-white);
  max-width: 640px;
  font-size: 15px;
  line-height: 1.75;
  opacity: 0.85;
}
.section-sub.dark { color: var(--lot-black); opacity: 0.85; }

/* ============= HERO (HOME) ============= */
.hero {
  background: var(--lot-black);
  padding: 80px 64px 60px;
  position: relative;
  overflow: hidden;
}
.hero::before {
  content: '';
  position: absolute; inset: 0;
  background-image:
    linear-gradient(45deg, var(--gridline-gray) 25%, transparent 25%, transparent 75%, var(--gridline-gray) 75%),
    linear-gradient(45deg, var(--gridline-gray) 25%, transparent 25%, transparent 75%, var(--gridline-gray) 75%);
  background-size: 8px 8px;
  background-position: 0 0, 4px 4px;
  opacity: 0.04;
  pointer-events: none;
}
.hero-grid {
  display: grid;
  grid-template-columns: 7fr 5fr;
  gap: 0;
  align-items: center;
  position: relative;
  z-index: 2;
}
.hero-headline {
  font-family: var(--font-pixel);
  font-size: 72px;
  line-height: 1.1;
  color: var(--revv-cyan);
  text-transform: uppercase;
  white-space: nowrap;
  margin: 24px 0 0;
}
.hero-headline .line-2 {
  color: var(--crt-white);
  display: block;
}
.hero-sub {
  margin-top: 24px;
  font-family: var(--font-mono);
  font-size: 16px;
  color: var(--crt-white);
  max-width: 520px;
  line-height: 1.75;
}
.hero-illustration {
  position: relative;
  width: 100%;
  max-width: 680px;
  margin-left: auto;
}

/* Browser window chrome */
.browser-window {
  border: 2px solid var(--revv-cyan);
  background: var(--screen-fog);
  box-shadow: 0 0 16px rgba(0,245,255,0.25);
}
.browser-bar {
  background: var(--screen-fog);
  border-bottom: 2px solid var(--revv-cyan);
  padding: 8px 12px;
  display: flex;
  align-items: center;
  gap: 10px;
}
.browser-dots { display: flex; gap: 6px; }
.browser-dot {
  width: 10px; height: 10px;
  border-radius: 50%;
}
.dot-magenta { background: var(--pixel-magenta); }
.dot-lime { background: var(--nitro-lime); }
.dot-cyan { background: var(--revv-cyan); }
.browser-url {
  flex: 1;
  font-family: var(--font-mono);
  font-size: 12px;
  color: var(--crt-white);
  background: var(--lot-black);
  padding: 4px 10px;
  border: 1px solid var(--gridline-gray);
}
.browser-content { padding: 0; }

/* ============= STATS ============= */
.stats-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  margin-top: 24px;
  position: relative;
  z-index: 2;
}
.stat-card {
  padding: 20px 28px 20px 28px;
  border-top: 2px solid var(--revv-cyan);
  border-right: 1px solid var(--gridline-gray);
  background: transparent;
}
.stat-card:last-child { border-right: none; }
.stat-cat {
  font-family: var(--font-accent);
  font-size: 9px;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--gridline-gray);
}
.stat-num {
  font-family: var(--font-mono);
  font-weight: 700;
  font-size: 56px;
  color: var(--nitro-lime);
  line-height: 1.05;
  margin-top: 6px;
}
.stat-desc {
  font-size: 13px;
  color: var(--crt-white);
  line-height: 1.6;
  margin-top: 12px;
  opacity: 0.9;
}
.stats-bg {
  position: relative;
  background: var(--screen-fog);
}
.stats-bg::before {
  content: '';
  position: absolute; inset: 0;
  background-image:
    linear-gradient(45deg, var(--gridline-gray) 25%, transparent 25%, transparent 75%, var(--gridline-gray) 75%),
    linear-gradient(45deg, var(--gridline-gray) 25%, transparent 25%, transparent 75%, var(--gridline-gray) 75%);
  background-size: 16px 16px;
  background-position: 0 0, 8px 8px;
  opacity: 0.12;
  pointer-events: none;
}

/* ============= FEATURE GRID (HOME) ============= */
.feature-block {
  display: grid;
  grid-template-columns: 4fr 8fr;
  gap: 0;
}
.feature-text {
  padding-right: 32px;
  border-right: 2px solid var(--turbo-purple);
}
.feature-text .section-title { font-size: 20px; }
.feature-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 16px;
  padding-left: 32px;
}
.feature-card {
  position: relative;
  background: var(--screen-fog);
  border: 2px solid var(--gridline-gray);
  padding: 28px;
  transition: border-color 0.15s linear;
}
.feature-card:hover { border-top-color: var(--revv-cyan); }
.feature-card.offset { transform: translateY(16px); }
.feature-icon {
  width: 40px; height: 40px;
  color: var(--revv-cyan);
}
.feature-card h3 {
  font-family: var(--font-pixel);
  font-size: 12px;
  color: var(--crt-white);
  margin-top: 16px;
  line-height: 1.5;
}
.feature-card p {
  font-size: 14px;
  margin-top: 12px;
  line-height: 1.7;
  color: var(--crt-white);
}
.feature-card::after {
  content: '';
  position: absolute;
  bottom: 8px; right: 8px;
  width: 4px; height: 4px;
  background: var(--turbo-purple);
}

/* ============= TIMELINE (HOME) ============= */
.timeline-row {
  margin-top: 32px;
  position: relative;
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 16px;
}
.timeline-row::before {
  content: '';
  position: absolute;
  left: 24px; right: 24px;
  top: 24px;
  height: 2px;
  background-image:
    repeating-linear-gradient(90deg, var(--revv-cyan) 0 8px, transparent 8px 14px);
  z-index: 1;
}
.tl-step { position: relative; z-index: 2; }
.tl-node {
  width: 48px; height: 48px;
  border: 3px solid var(--revv-cyan);
  background: var(--screen-fog);
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-mono);
  font-weight: 700;
  font-size: 20px;
  color: var(--nitro-lime);
  border-radius: 50%;
}
.tl-step h4 {
  margin-top: 20px;
  font-family: var(--font-accent);
  font-size: 11px;
  letter-spacing: 0.12em;
  color: var(--revv-cyan);
  text-transform: uppercase;
}
.tl-step p {
  margin-top: 8px;
  font-size: 14px;
  color: var(--crt-white);
}

/* ============= TESTIMONIALS ============= */
.testimonials-stack {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
  margin-top: 28px;
  align-items: start;
}
.tcard-1 { transform: translateY(0); }
.tcard-2 { transform: translateY(32px); }
.tcard-3 { transform: translateY(48px); }
.testimonial-card {
  position: relative;
  background: var(--lot-black);
  border: 2px solid var(--crt-white);
  padding: 28px;
  color: var(--crt-white);
}
.testimonial-card .quote-mark {
  position: absolute;
  top: -28px; left: 16px;
  font-family: var(--font-mono);
  color: var(--nitro-lime);
  font-size: 56px;
  line-height: 1;
}
.testimonial-card p {
  font-size: 14px;
  line-height: 1.75;
  color: var(--crt-white);
}
.testimonial-card .attribution {
  margin-top: 16px;
  font-family: var(--font-accent);
  letter-spacing: 0.12em;
  font-size: 10px;
  text-transform: uppercase;
  color: var(--revv-cyan);
}
.rating-sticker {
  position: absolute;
  bottom: -14px; right: -14px;
  background: var(--pixel-magenta);
  border: 3px solid var(--pixel-magenta);
  color: var(--crt-white);
  font-family: var(--font-accent);
  font-size: 9px;
  padding: 4px 10px;
  letter-spacing: 0.12em;
  transform: rotate(4deg);
}

/* ============= FOOTER ============= */
.site-footer {
  background: var(--lot-black);
  border-top: 8px solid var(--turbo-purple);
  padding: 48px 64px 36px;
  color: var(--crt-white);
}
.footer-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr;
  gap: 32px;
  margin-bottom: 32px;
}
.footer-brand .nav-logo { font-size: 22px; margin-bottom: 12px; }
.footer-grid h4 {
  font-family: var(--font-accent);
  font-size: 11px;
  letter-spacing: 0.12em;
  color: var(--nitro-lime);
  text-transform: uppercase;
  margin: 0 0 12px;
}
.footer-grid ul { list-style: none; padding: 0; margin: 0; }
.footer-grid li { font-size: 13px; margin-bottom: 8px; }
.footer-grid a { color: var(--crt-white); }
.footer-grid a:hover { color: var(--revv-cyan); }
.footer-bottom {
  border-top: 1px solid var(--gridline-gray);
  padding-top: 16px;
  font-size: 11px;
  font-family: var(--font-mono);
  color: var(--gridline-gray);
  display: flex;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 12px;
}

/* ============= PRODUCT — PAGE HEADER ============= */
.page-header {
  position: relative;
  background: var(--lot-black);
  padding: 80px 64px;
  overflow: hidden;
}
.page-header.car-pattern::before {
  content: '';
  position: absolute; inset: 0;
  background-image: url("assets/car-tile.svg");
  background-size: 80px 60px;
  background-repeat: repeat;
  opacity: 0.18;
  pointer-events: none;
}
.page-header h1 {
  font-family: var(--font-pixel);
  font-size: 36px;
  color: var(--crt-white);
  margin-top: 16px;
  line-height: 1.4;
}
.page-header .ph-sub {
  margin-top: 20px;
  font-size: 15px;
  color: var(--crt-white);
  opacity: 0.85;
  max-width: 520px;
}
.page-header.checker-bottom { padding-bottom: 80px; }

/* ============= PRODUCT — FILTER PANEL ============= */
.filter-section {
  background: var(--screen-fog);
  padding: 48px 64px;
}
.filter-frame {
  border: 2px solid var(--revv-cyan);
  background: var(--lot-black);
  margin-top: 20px;
}
.filter-frame .browser-bar {
  background: var(--gridline-gray);
  height: 24px;
  padding: 0 12px;
  display: flex; align-items: center; gap: 12px;
  border-bottom: 2px solid var(--revv-cyan);
  position: relative;
}
.filter-frame .browser-url {
  flex: none;
  background: transparent;
  border: none;
  color: var(--crt-white);
  font-size: 11px;
  position: absolute;
  left: 50%;
  transform: translateX(-50%);
}
.filter-frame .filter-body {
  padding: 32px;
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 16px;
}
.filter-field label {
  display: block;
  font-family: var(--font-accent);
  font-size: 10px;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--crt-white);
  margin-bottom: 8px;
}
.filter-field input[type=text] {
  width: 100%;
  background: var(--lot-black);
  border: 2px solid var(--revv-cyan);
  color: var(--crt-white);
  font-family: var(--font-mono);
  font-size: 14px;
  padding: 10px 12px;
}
.filter-field input::placeholder { color: var(--gridline-gray); }
.range-bar {
  width: 100%;
  height: 12px;
  background: var(--gridline-gray);
  position: relative;
  margin-top: 6px;
}
.range-bar .fill {
  position: absolute;
  top: 0; height: 12px;
  background: var(--revv-cyan);
  left: 20%; right: 30%;
}
.range-bar.purple .fill { background: var(--turbo-purple); }
.range-bar .thumb {
  position: absolute;
  top: -2px;
  width: 12px; height: 16px;
  background: var(--nitro-lime);
}
.range-bar .thumb.left { left: calc(20% - 6px); }
.range-bar .thumb.right { right: calc(30% - 6px); }
.range-meta {
  display: flex;
  justify-content: space-between;
  margin-top: 8px;
  font-size: 12px;
  color: var(--crt-white);
}
.chips { display: flex; flex-wrap: wrap; gap: 6px; }
.chip {
  font-family: var(--font-accent);
  text-transform: uppercase;
  letter-spacing: 0.12em;
  font-size: 10px;
  background: var(--gridline-gray);
  border: 2px solid var(--gridline-gray);
  color: var(--crt-white);
  padding: 6px 10px;
  cursor: pointer;
}
.chip.active {
  border-color: var(--revv-cyan);
  color: var(--revv-cyan);
  background: var(--lot-black);
}
.filter-search-btn {
  display: block;
  width: calc(100% - 64px);
  margin: 0 32px 32px;
  background: var(--revv-cyan);
  color: var(--lot-black);
  font-family: var(--font-accent);
  font-size: 12px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  border: 2px solid var(--lot-black);
  padding: 16px;
  cursor: pointer;
}

/* ============= PRODUCT — LISTINGS ============= */
.signature-section {
  position: relative;
  background: var(--lot-black);
  padding: 72px 0 64px;
  overflow: hidden;
}
.signature-section .container { padding: 0 64px; }
.signature-headline {
  font-family: var(--font-pixel);
  font-size: 64px;
  color: var(--revv-cyan);
  text-transform: uppercase;
  white-space: nowrap;
  margin-top: 12px;
  line-height: 1.1;
}
.signature-rule {
  height: 4px;
  width: 100%;
  background: var(--turbo-purple);
  margin-top: 16px;
}
.signature-sub {
  margin-top: 20px;
  font-size: 14px;
  color: var(--crt-white);
  opacity: 0.7;
}
.listing-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 20px 16px;
  margin-top: 40px;
}
.listing-card {
  position: relative;
  background: var(--screen-fog);
  border: 2px solid var(--revv-cyan);
  padding: 24px 20px 16px;
  display: flex;
  flex-direction: column;
}
.listing-badge {
  position: absolute;
  top: -10px; left: -10px;
  font-family: var(--font-accent);
  font-size: 9px;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  padding: 6px 10px;
  border: 2px solid var(--lot-black);
  z-index: 2;
}
.badge-best { background: var(--nitro-lime); color: var(--lot-black); }
.badge-pop { background: var(--revv-cyan); color: var(--lot-black); }
.badge-fast { background: var(--pixel-magenta); color: var(--crt-white); }
.badge-low { background: var(--turbo-purple); color: var(--crt-white); }
.badge-lux { background: var(--gridline-gray); color: var(--crt-white); }
.badge-ev { background: var(--pixel-magenta); color: var(--crt-white); }
.listing-title {
  font-family: var(--font-pixel);
  font-size: 13px;
  color: var(--crt-white);
  line-height: 1.5;
}
.listing-price {
  display: inline-block;
  margin-top: 8px;
  font-family: var(--font-pixel);
  font-size: 13px;
  color: var(--nitro-lime);
}
.listing-spec {
  font-family: var(--font-mono);
  font-size: 12px;
  color: var(--crt-white);
  opacity: 0.85;
  margin-top: 8px;
}
.listing-status {
  display: flex; align-items: center; gap: 8px;
  margin-top: 6px;
  font-family: var(--font-mono);
  font-size: 11px;
  color: var(--crt-white);
}
.listing-status::before {
  content: '';
  width: 8px; height: 8px;
  background: var(--nitro-lime);
  border-radius: 50%;
}
.listing-loc {
  display: inline-block;
  margin-top: 10px;
  font-family: var(--font-accent);
  font-size: 10px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  background: var(--gridline-gray);
  color: var(--crt-white);
  padding: 4px 8px;
  align-self: flex-start;
}
.listing-divider {
  border: 0;
  border-top: 1px solid var(--gridline-gray);
  margin: 12px 0;
}
.listing-cta-row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px;
}
.listing-btn {
  font-family: var(--font-accent);
  text-transform: uppercase;
  letter-spacing: 0.12em;
  font-size: 10px;
  text-align: center;
  padding: 10px 6px;
  border: 2px solid var(--revv-cyan);
  background: transparent;
  color: var(--revv-cyan);
  text-decoration: none;
  cursor: pointer;
}
.listing-btn.primary { background: var(--revv-cyan); color: var(--lot-black); }

/* ============= COMPARISON ============= */
.compare-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  margin-top: 40px;
}
.compare-panel {
  background: var(--screen-fog);
  border: 2px solid var(--turbo-purple);
}
.compare-panel + .compare-panel { border-left: 0; }
.compare-header {
  background: var(--turbo-purple);
  height: 40px;
  display: flex; align-items: center; justify-content: center;
  font-family: var(--font-pixel);
  font-size: 14px;
  color: var(--lot-black);
}
.compare-body { padding: 32px; }
.compare-body p { font-size: 15px; }
.compare-metric {
  display: flex; justify-content: space-between; align-items: baseline;
  padding: 12px 0;
  border-bottom: 1px solid var(--gridline-gray);
}
.compare-metric:last-of-type { border-bottom: none; }
.compare-metric .label {
  font-family: var(--font-accent);
  font-size: 10px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}
.compare-metric .value {
  font-family: var(--font-mono);
  font-size: 20px;
  color: var(--nitro-lime);
}
.compare-cta { margin-top: 28px; }
.compare-cta .listing-btn { display: block; width: 100%; }

/* ============= PURPLE CTA ============= */
.cta-block {
  background: var(--turbo-purple);
  text-align: center;
  padding: 96px 48px;
  position: relative;
}
.cta-block h2 {
  font-family: var(--font-pixel);
  color: var(--lot-black);
  font-size: 28px;
  max-width: 720px;
  margin: 12px auto 0;
}
.cta-block p {
  color: var(--lot-black);
  opacity: 0.85;
  max-width: 560px;
  margin: 20px auto 0;
  font-size: 15px;
}
.cta-block .btn-row { justify-content: center; }

/* ============= SPECS PAGE ============= */
.specs-header {
  background: var(--lot-black);
  position: relative;
  padding: 80px 64px 64px;
  border-top: 3px solid var(--turbo-purple);
}
.specs-header::before {
  content: '';
  position: absolute; inset: 0;
  background-image:
    linear-gradient(45deg, var(--gridline-gray) 25%, transparent 25%, transparent 75%, var(--gridline-gray) 75%),
    linear-gradient(45deg, var(--gridline-gray) 25%, transparent 25%, transparent 75%, var(--gridline-gray) 75%);
  background-size: 24px 24px;
  background-position: 0 0, 12px 12px;
  opacity: 0.30;
  pointer-events: none;
}
.specs-header-grid {
  position: relative;
  z-index: 2;
  display: grid;
  grid-template-columns: 7fr 5fr;
  gap: 48px;
  align-items: start;
}
.spec-h1 {
  font-family: var(--font-pixel);
  font-size: 32px;
  color: var(--revv-cyan);
  margin-top: 16px;
  line-height: 1.4;
}
.spec-status {
  margin-top: 24px;
  font-family: var(--font-mono);
  font-size: 14px;
  color: var(--crt-white);
}
.spec-status .sep { color: var(--nitro-lime); padding: 0 6px; }
.spec-cta-stack {
  display: flex; flex-direction: column; gap: 12px;
  margin-top: 32px; align-items: flex-start;
}
.dash-mockup {
  border: 4px solid var(--turbo-purple);
  background: var(--screen-fog);
  box-shadow: 0 0 16px rgba(0,245,255,0.35);
}
.dash-mockup .browser-bar {
  background: var(--gridline-gray);
  border-bottom: 2px solid var(--turbo-purple);
}
.dash-body {
  padding: 24px;
  position: relative;
}
.dash-make {
  font-family: var(--font-pixel);
  font-size: 14px;
  color: var(--revv-cyan);
}
.dash-grade {
  position: absolute;
  top: 16px; right: 16px;
  background: var(--nitro-lime);
  color: var(--lot-black);
  font-family: var(--font-accent);
  font-size: 10px;
  letter-spacing: 0.12em;
  padding: 4px 8px;
  border: 2px solid var(--lot-black);
}
.dash-list { margin-top: 16px; }
.dash-row {
  display: flex; justify-content: space-between;
  padding: 6px 0;
  border-bottom: 1px dashed var(--gridline-gray);
  font-family: var(--font-mono);
  font-size: 12px;
}
.dash-row .k { color: var(--crt-white); opacity: 0.7; }
.dash-row .v { color: var(--crt-white); }
.dash-row.lime .v { color: var(--nitro-lime); }

/* Specs grid */
.specs-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 16px;
  margin-top: 32px;
}
.spec-cell {
  background: var(--lot-black);
  border: 2px solid var(--turbo-purple);
  padding: 28px 20px 20px;
  position: relative;
  transition: border-color 0.15s linear, box-shadow 0.15s linear;
}
.spec-cell:hover { border-color: var(--revv-cyan); box-shadow: 0 0 8px rgba(0,245,255,0.3); }
.spec-cell .cat-badge {
  position: absolute;
  top: 8px; left: 8px;
  font-family: var(--font-accent);
  font-size: 9px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--turbo-purple);
}
.spec-cell h3 {
  font-family: var(--font-accent);
  font-size: 12px;
  letter-spacing: 0.12em;
  color: var(--revv-cyan);
  text-transform: uppercase;
}
.spec-cell p {
  font-family: var(--font-mono);
  font-size: 14px;
  color: var(--crt-white);
  margin-top: 8px;
  line-height: 1.6;
}

/* Inspection / VERIFIED */
.verified-section {
  position: relative;
  background: var(--lot-black);
  padding: 96px 64px;
  overflow: hidden;
  text-align: center;
}
.verified-stamp {
  position: absolute;
  font-family: var(--font-pixel);
  font-size: 120px;
  color: var(--nitro-lime);
  opacity: 0.18;
  white-space: nowrap;
  top: 50%; left: 50%;
  transform: translate(-50%, -50%) rotate(-15deg);
  pointer-events: none;
  z-index: 1;
}
.verified-section .container { position: relative; z-index: 2; }
.verified-cards {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 20px;
  margin-top: 48px;
  position: relative;
  z-index: 2;
}
.vcard {
  background: var(--screen-fog);
  border: 3px solid var(--nitro-lime);
  padding: 32px 24px;
  text-align: left;
}
.vcard .system {
  font-family: var(--font-accent);
  font-size: 9px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--turbo-purple);
}
.vcard .num {
  font-family: var(--font-pixel);
  font-size: 22px;
  color: var(--nitro-lime);
  margin-top: 12px;
  line-height: 1.2;
}
.vcard .desc {
  margin-top: 12px;
  font-family: var(--font-mono);
  font-size: 13px;
  color: var(--crt-white);
  line-height: 1.6;
}

.inspect-chart {
  margin: 40px auto 0;
  max-width: 800px;
  background: var(--screen-fog);
  border: 2px solid var(--turbo-purple);
  padding: 24px;
  position: relative;
  z-index: 2;
}
.chart-row {
  display: grid;
  grid-template-columns: 110px 1fr 36px;
  gap: 12px;
  align-items: center;
  margin-bottom: 8px;
  font-family: var(--font-mono);
  font-size: 12px;
  color: var(--crt-white);
}
.chart-bar {
  position: relative;
  height: 14px;
  background: var(--turbo-purple);
}
.chart-bar .fill {
  position: absolute; left: 0; top: 0; bottom: 0;
  background: var(--revv-cyan);
}
.chart-row .num { text-align: right; color: var(--nitro-lime); }

/* Vehicle history timeline */
.history-section { background: var(--screen-fog); padding: 80px 64px; }
.history-grid {
  display: grid;
  grid-template-columns: 2fr 10fr;
  gap: 32px;
  margin-top: 32px;
  position: relative;
}
.history-rail {
  position: relative;
  border-right: 0;
  padding-right: 24px;
}
.history-rail::before {
  content: '';
  position: absolute;
  right: 0;
  top: 8px; bottom: 8px;
  width: 3px;
  background: var(--turbo-purple);
}
.history-events { padding-left: 32px; position: relative; }
.history-event {
  position: relative;
  padding: 8px 0 32px;
  border-bottom: 2px solid var(--gridline-gray);
  margin-bottom: 32px;
}
.history-event:last-child { border-bottom: none; margin-bottom: 0; }
.history-event::before {
  content: '';
  position: absolute;
  left: -45px; top: 14px;
  width: 16px; height: 16px;
  background: var(--nitro-lime);
}
.history-event.current::before {
  width: 24px; height: 24px;
  left: -49px; top: 10px;
  border: 2px solid var(--revv-cyan);
}
.history-event.current {
  background: var(--lot-black);
  border: 2px solid var(--revv-cyan);
  box-shadow: 0 0 12px rgba(0,245,255,0.25);
  padding: 16px;
}
.history-event h4 {
  font-family: var(--font-accent);
  font-size: 12px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--nitro-lime);
}
.history-event p {
  margin-top: 8px;
  font-family: var(--font-mono);
  font-size: 14px;
  color: var(--crt-white);
}
.history-sub {
  margin-top: 12px;
  font-family: var(--font-mono);
  font-size: 15px;
  color: var(--revv-cyan);
}
.history-sub-rule {
  height: 2px; background: var(--turbo-purple);
  width: 100%;
  margin-top: 24px; margin-bottom: 24px;
}

/* Magenta CTA close (specs) */
.magenta-cta {
  background: var(--pixel-magenta);
  text-align: center;
  padding: 96px 48px;
  position: relative;
}
.magenta-cta h2 {
  font-family: var(--font-pixel);
  font-size: 32px;
  color: var(--lot-black);
  max-width: 720px;
  margin: 12px auto 0;
  line-height: 1.4;
}
.magenta-cta p {
  color: var(--lot-black);
  opacity: 0.85;
  margin: 16px auto 0;
  max-width: 560px;
}
.magenta-cta .btn-row { justify-content: center; }
.magenta-cta .trust-line {
  margin-top: 28px;
  font-family: var(--font-mono);
  font-size: 12px;
  color: var(--lot-black);
  letter-spacing: 0.05em;
}
.magenta-cta .trust-line .star { color: var(--nitro-lime); }
.magenta-cta::before {
  content: '';
  position: absolute; inset: 0;
  background-image:
    linear-gradient(45deg, rgba(0,0,0,0.18) 25%, transparent 25%, transparent 75%, rgba(0,0,0,0.18) 75%),
    linear-gradient(45deg, rgba(0,0,0,0.18) 25%, transparent 25%, transparent 75%, rgba(0,0,0,0.18) 75%);
  background-size: 32px 32px;
  background-position: 0 0, 16px 16px;
  opacity: 0.3;
  pointer-events: none;
}

/* ============= GALLERY PAGE ============= */
.gallery-header {
  background: var(--lot-black);
  padding: 28px 64px;
  border-top: 0;
}
.gallery-header-grid {
  display: grid;
  grid-template-columns: 8fr 4fr;
  gap: 32px;
  align-items: center;
  margin-top: 8px;
}
.gallery-h1 {
  font-family: var(--font-pixel);
  font-size: 36px;
  color: var(--crt-white);
  line-height: 1.4;
  margin-top: 12px;
}
.gallery-h1 .magenta-dot { color: var(--pixel-magenta); }
.gallery-stat-strip {
  margin-top: 16px;
  font-family: var(--font-mono);
  font-size: 14px;
  color: var(--crt-white);
}
.gallery-stat-strip .sep { color: var(--revv-cyan); padding: 0 6px; }
.gallery-stat-strip .hot { color: var(--pixel-magenta); }
.gallery-cta-stack {
  display: flex; flex-direction: column; gap: 12px;
}
.gallery-cta-stack .btn { width: 100%; box-shadow: 0 0 8px rgba(0,245,255,0.4); }

/* Filmstrip */
.filmstrip-section {
  position: relative;
  background: var(--lot-black);
  padding: 40px 0 48px;
  overflow: hidden;
}
.filmstrip-section .filmstrip-header {
  padding: 0 64px;
  display: grid;
  grid-template-columns: 8fr 4fr;
  gap: 24px;
  align-items: start;
}
.exterior-watermark {
  position: absolute;
  font-family: var(--font-pixel);
  font-size: 96px;
  color: var(--turbo-purple);
  opacity: 0.15;
  top: 50%; left: 40px;
  transform: translateY(-30%);
  white-space: nowrap;
  pointer-events: none;
  z-index: 1;
}
.hotspot-diagram {
  background: var(--screen-fog);
  border: 2px solid var(--gridline-gray);
  padding: 16px;
  max-width: 320px;
  justify-self: end;
}
.filmstrip {
  display: flex; gap: 12px;
  margin-top: 24px;
  padding: 12px 0 12px 80px;
  overflow-x: auto;
  position: relative;
  z-index: 2;
}
.film-tile {
  flex: 0 0 340px;
  width: 340px;
  height: 260px;
  background: var(--screen-fog);
  border: 3px solid var(--revv-cyan);
  box-shadow: 0 0 10px rgba(0,245,255,0.5);
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
}
.film-tile:hover { box-shadow: 0 0 18px rgba(0,245,255,0.8); }
.film-tile .photo-placeholder {
  width: 80%; height: 70%;
  background:
    linear-gradient(135deg, var(--gridline-gray) 0%, var(--screen-fog) 100%);
  position: relative;
  border: 1px solid var(--gridline-gray);
  display: flex;
  align-items: center;
  justify-content: center;
}
.film-tile .photo-placeholder svg { width: 60%; height: 60%; opacity: 0.6; }
.film-tile .tile-overlay {
  position: absolute;
  bottom: 0; left: 0; right: 0;
  background: rgba(10,10,10,0.85);
  padding: 12px 16px;
  display: flex; justify-content: space-between; align-items: center;
}
.tile-overlay .ttitle {
  font-family: var(--font-accent);
  font-size: 10px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--crt-white);
}
.tile-overlay .pcount {
  background: var(--nitro-lime);
  color: var(--lot-black);
  font-family: var(--font-accent);
  font-size: 10px;
  letter-spacing: 0.12em;
  padding: 3px 8px;
}
.film-cap {
  font-family: var(--font-mono);
  font-size: 13px;
  color: var(--crt-white);
  opacity: 0.65;
  padding: 0 64px;
  margin-top: 12px;
  display: flex;
  gap: 12px;
}
.film-cap .item { flex: 0 0 340px; max-width: 340px; }

/* Interior tabs */
.interior-section {
  background: var(--screen-fog);
  padding: 56px 64px;
}
.tab-panel {
  margin-top: 32px;
  display: grid;
  grid-template-columns: 2fr 10fr;
  border: 2px solid var(--gridline-gray);
}
.tab-list {
  border-right: 1px solid var(--gridline-gray);
}
.tab {
  display: block;
  padding: 16px 16px;
  border-left: 2px solid var(--gridline-gray);
  border-bottom: 1px solid var(--gridline-gray);
  font-family: var(--font-accent);
  font-size: 10px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: rgba(232,240,242,0.5);
  background: transparent;
  text-decoration: none;
  cursor: pointer;
}
.tab.active {
  border-left: 4px solid var(--turbo-purple);
  background: rgba(204,0,255,0.08);
  color: var(--turbo-purple);
}
.tab:last-child { border-bottom: none; }
.tab-content { padding: 24px; }
.tab-meta {
  display: flex; align-items: center; gap: 12px;
}
.tab-meta .ctitle { font-family: var(--font-mono); font-size: 13px; color: var(--revv-cyan); }
.tab-meta .badge {
  background: var(--lot-black);
  color: var(--nitro-lime);
  font-family: var(--font-accent);
  font-size: 10px;
  letter-spacing: 0.12em;
  padding: 3px 7px;
  border: 1px solid var(--nitro-lime);
}
.tab-desc { margin-top: 8px; font-size: 14px; color: var(--crt-white); opacity: 0.8; max-width: 600px; }
.photo-2x2 {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 12px;
  margin-top: 16px;
}
.mini-photo {
  height: 165px;
  background: var(--screen-fog);
  border: 3px solid var(--revv-cyan);
  box-shadow: 0 0 8px rgba(0,245,255,0.4);
  position: relative;
  display: flex; align-items: center; justify-content: center;
}
.mini-photo .photo-placeholder {
  width: 80%; height: 70%;
  background: linear-gradient(135deg, var(--gridline-gray) 0%, var(--lot-black) 100%);
  display: flex; align-items: center; justify-content: center;
}
.mini-photo .tile-overlay {
  background: rgba(10,10,10,0.8);
  padding: 8px 12px;
  height: 30px;
  font-size: 10px;
}
.mini-photo .ttitle { color: var(--crt-white); }
.mini-photo .view { color: var(--revv-cyan); font-family: var(--font-accent); font-size: 10px; letter-spacing: 0.12em; }

/* Mechanical */
.mech-section { background: var(--lot-black); padding: 48px 64px 56px; }
.mech-grid {
  display: grid;
  grid-template-columns: 3fr 9fr;
  margin-top: 32px;
  border-top: 1px solid var(--gridline-gray);
}
.mech-index {
  border-right: 2px solid var(--gridline-gray);
}
.mech-row {
  display: flex; align-items: center; gap: 16px;
  padding: 0 16px;
  height: 100px;
  border-bottom: 1px solid var(--gridline-gray);
  border-left: 3px solid transparent;
  cursor: pointer;
}
.mech-row.active {
  border-left-color: var(--nitro-lime);
  background: rgba(46,46,68,0.4);
}
.mech-row:last-child { border-bottom: none; }
.mech-row .icon { width: 32px; height: 32px; color: var(--revv-cyan); flex: none; }
.mech-row .title {
  font-family: var(--font-accent);
  font-size: 11px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--crt-white);
  flex: 1;
}
.mech-row .pcount {
  background: var(--nitro-lime);
  color: var(--lot-black);
  font-family: var(--font-accent);
  font-size: 10px;
  letter-spacing: 0.12em;
  padding: 3px 7px;
}
.mech-photos {
  padding: 16px;
}
.mech-photo-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 12px;
}
.mech-photo {
  height: 165px;
  background: var(--screen-fog);
  border: 3px solid var(--revv-cyan);
  box-shadow: 0 0 8px rgba(0,245,255,0.4);
  display: flex; align-items: center; justify-content: center;
}
.mech-photo .photo-placeholder {
  width: 80%; height: 70%;
  background: linear-gradient(135deg, var(--gridline-gray) 0%, var(--lot-black) 100%);
  display: flex; align-items: center; justify-content: center;
}
.mech-photo svg { width: 60%; height: 60%; opacity: 0.6; }
.mech-condition {
  margin-top: 16px;
  padding-top: 16px;
  border-top: 1px solid var(--revv-cyan);
  font-size: 14px;
  color: var(--crt-white);
  opacity: 0.85;
  max-width: 600px;
}

/* Gallery CTA close (purple) */
.gallery-cta-close {
  background: var(--turbo-purple);
  position: relative;
  padding: 80px 48px;
  text-align: center;
}
.gallery-cta-close h2 {
  font-family: var(--font-pixel);
  font-size: 36px;
  margin: 16px auto 0;
  max-width: 780px;
  color: var(--crt-white);
  line-height: 1.4;
}
.gallery-cta-close .line1 { color: var(--nitro-lime); display: block; }
.gallery-cta-close .strikeword { color: var(--nitro-lime); position: relative; display: inline-block; }
.gallery-cta-close .strikeword::after {
  content: '';
  position: absolute; left: 0; right: 0; top: 50%;
  height: 4px; background: var(--pixel-magenta);
}
.gallery-cta-close p {
  margin: 28px auto 0;
  max-width: 560px;
  font-size: 16px;
  color: var(--crt-white);
  opacity: 0.85;
}
.gallery-cta-close .btn-row { margin-top: 32px; justify-content: center; }
.gallery-cta-close .btn-primary-lime {
  background: var(--nitro-lime);
  border-color: var(--lot-black);
  color: var(--lot-black);
  min-width: 340px;
}
.gallery-cta-close .btn-primary-lime:hover { background: var(--crt-white); }
.gallery-cta-close .btn-out-white {
  background: transparent;
  border-color: var(--crt-white);
  color: var(--crt-white);
}
.gallery-cta-close .btn-out-white:hover { background: var(--nitro-lime); border-color: var(--nitro-lime); color: var(--lot-black); }

/* ============= RESERVE PAGE ============= */
.reserve-header {
  position: relative;
  background: var(--lot-black);
  padding: 64px 64px 80px;
  overflow: hidden;
  min-height: 480px;
}
.reserve-stamp {
  position: absolute;
  font-family: var(--font-pixel);
  font-size: 80px;
  color: var(--turbo-purple);
  opacity: 0.18;
  top: 50%; left: 50%;
  transform: translate(-50%,-50%) rotate(-8deg);
  white-space: nowrap;
  pointer-events: none;
  z-index: 1;
}
.reserve-grid {
  position: relative; z-index: 2;
  display: grid;
  grid-template-columns: 7fr 5fr;
  gap: 32px;
  align-items: end;
}
.reserve-h1 {
  font-family: var(--font-pixel);
  font-size: 40px;
  color: var(--crt-white);
  line-height: 1.2;
  margin-top: 16px;
}
.reserve-sub {
  margin-top: 24px;
  font-family: var(--font-mono);
  font-size: 17px;
  line-height: 1.75;
  color: var(--crt-white);
  opacity: 0.85;
  max-width: 520px;
}
.reserve-illo { align-self: end; }

/* Story block */
.story-section {
  background: var(--lot-black);
  padding: 48px 64px;
}
.story-frame {
  max-width: 860px;
  margin: 0 auto;
  border: 2px solid var(--revv-cyan);
  background: var(--screen-fog);
}
.story-bar {
  height: 36px;
  background: var(--gridline-gray);
  display: flex; align-items: center; gap: 8px;
  padding: 0 14px;
  border-bottom: 2px solid var(--revv-cyan);
}
.story-bar .browser-dot { width: 10px; height: 10px; border-radius: 50%; }
.story-body { padding: 32px; }
.story-body h2 {
  font-family: var(--font-pixel);
  font-size: 22px;
  margin-top: 12px;
  color: var(--crt-white);
  line-height: 1.4;
}
.story-specs {
  margin-top: 16px;
  font-family: var(--font-mono);
  font-size: 15px;
  color: var(--nitro-lime);
  display: flex; flex-wrap: wrap; align-items: center; gap: 12px;
}
.story-badge {
  font-family: var(--font-accent);
  font-size: 10px;
  letter-spacing: 0.12em;
  background: var(--nitro-lime);
  color: var(--lot-black);
  border: 4px solid var(--lot-black);
  padding: 4px 8px;
}
.story-body .body-copy {
  margin-top: 20px;
  font-size: 15px;
  color: var(--crt-white);
  opacity: 0.85;
  max-width: 640px;
}
.story-table {
  margin-top: 28px;
  border-top: 2px solid var(--revv-cyan);
  border-bottom: 2px solid var(--revv-cyan);
}
.story-row {
  display: flex; justify-content: space-between; align-items: baseline;
  padding: 12px 0;
  border-bottom: 1px dashed var(--gridline-gray);
}
.story-row:last-child { border-bottom: none; }
.story-row .lbl {
  font-family: var(--font-mono);
  font-weight: 700;
  font-size: 14px;
  color: var(--crt-white);
}
.story-row .val { font-family: var(--font-mono); font-size: 14px; color: var(--crt-white); }
.story-row.hold .val { color: var(--pixel-magenta); font-weight: 700; }
.story-row.total .val { color: var(--nitro-lime); }

/* Form section */
.form-section {
  background: var(--screen-fog);
  padding: 64px;
}
.form-grid {
  display: grid;
  grid-template-columns: 7fr 5fr;
  gap: 32px;
}
.step-chip {
  display: inline-block;
  font-family: var(--font-accent);
  font-size: 10px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--gridline-gray);
  background: var(--revv-cyan);
  border: 2px solid var(--revv-cyan);
  padding: 4px 10px;
  margin-bottom: 12px;
}
.form-list { display: grid; gap: 20px; margin-top: 28px; }
.form-field label {
  display: block;
  font-family: var(--font-accent);
  font-size: 10px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--crt-white);
  margin-bottom: 8px;
}
.form-field input, .form-field select {
  width: 100%;
  background: var(--lot-black);
  color: var(--crt-white);
  font-family: var(--font-mono);
  font-size: 15px;
  padding: 14px;
  border: 2px solid var(--gridline-gray);
  outline: none;
}
.form-field input:focus, .form-field select:focus { border-color: var(--revv-cyan); }
.form-field .desc {
  margin-top: 6px;
  font-family: var(--font-mono);
  font-size: 13px;
  color: var(--gridline-gray);
}
.radio-group { display: flex; flex-direction: column; gap: 8px; }
.radio-group label {
  display: flex; align-items: center; gap: 10px;
  font-family: var(--font-mono);
  font-size: 14px;
  color: var(--crt-white);
  text-transform: none;
  letter-spacing: 0;
  cursor: pointer;
}
.radio-square {
  display: inline-block;
  width: 14px; height: 14px;
  background: var(--lot-black);
  border: 2px solid var(--revv-cyan);
  flex: none;
}
.form-cta {
  margin-top: 32px;
  display: block;
  width: 100%;
  background: var(--revv-cyan);
  color: var(--lot-black);
  font-family: var(--font-accent);
  font-size: 12px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  border: 2px solid var(--revv-cyan);
  padding: 16px;
  cursor: pointer;
  text-align: center;
}
.form-cta:hover { background: var(--nitro-lime); border-color: var(--nitro-lime); }

.trust-sidebar {
  background: var(--screen-fog);
  border: 2px solid var(--turbo-purple);
  padding: 32px;
}
.trust-sidebar .eyebrow { color: var(--turbo-purple); }
.trust-sidebar ul {
  list-style: none; padding: 0; margin: 16px 0 24px;
  display: flex; flex-direction: column; gap: 12px;
}
.trust-sidebar li {
  font-family: var(--font-mono);
  font-size: 14px;
  color: var(--crt-white);
  display: flex; gap: 10px;
}
.trust-check {
  width: 16px; height: 16px;
  background: var(--nitro-lime);
  flex: none;
  display: inline-block;
  position: relative;
}
.trust-check::after {
  content: '';
  position: absolute;
  left: 4px; top: 1px;
  width: 4px; height: 8px;
  border: solid var(--lot-black);
  border-width: 0 2px 2px 0;
  transform: rotate(45deg);
}
.secure-badge {
  font-family: var(--font-accent);
  font-size: 10px;
  letter-spacing: 0.12em;
  background: var(--pixel-magenta);
  color: var(--crt-white);
  padding: 6px 10px;
  display: inline-flex;
  gap: 6px; align-items: center;
}
.padlock-mini {
  width: 12px; height: 14px;
  border: 2px solid var(--crt-white);
  position: relative;
}
.padlock-mini::before {
  content: '';
  position: absolute;
  width: 6px; height: 5px;
  border: 2px solid var(--crt-white);
  border-bottom: 0;
  top: -5px; left: 1px;
}

/* Guarantee grid (Reserve s4) */
.guarantee-section {
  background: var(--turbo-purple);
  padding: 72px 48px;
  text-align: center;
}
.guarantee-section .eyebrow { color: var(--lot-black); }
.guarantee-section .eyebrow::before { background: var(--lot-black); }
.guarantee-section h2 {
  font-family: var(--font-pixel);
  font-size: 28px;
  color: var(--lot-black);
  margin-top: 16px;
}
.guarantee-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 16px;
  max-width: 1000px;
  margin: 40px auto 0;
}
.gcard {
  background: var(--screen-fog);
  border: 2px solid var(--lot-black);
  padding: 24px;
  text-align: center;
}
.gcard .icon { width: 40px; height: 40px; margin: 0 auto; color: var(--revv-cyan); }
.gcard.alt .icon { color: var(--nitro-lime); }
.gcard h3 {
  font-family: var(--font-pixel);
  font-size: 12px;
  color: var(--crt-white);
  margin-top: 12px;
  line-height: 1.5;
}
.gcard p {
  margin-top: 10px;
  font-size: 14px;
  color: var(--crt-white);
  opacity: 0.85;
  line-height: 1.6;
}

/* FAQ */
.faq-section {
  background: var(--lot-black);
  padding: 80px 64px 0;
}
.faq-wrap {
  max-width: 760px;
  margin: 0 auto;
  text-align: center;
}
.faq-wrap h2 {
  font-family: var(--font-pixel);
  font-size: 20px;
  color: var(--crt-white);
  margin-top: 20px;
  line-height: 1.6;
}
.faq-wrap h2 .cyan { color: var(--revv-cyan); }
.faq-list {
  margin: 32px 0 0;
  border-top: 1px solid var(--gridline-gray);
  border-bottom: 1px solid var(--gridline-gray);
  text-align: left;
}
.faq-row {
  border-bottom: 1px solid var(--gridline-gray);
  padding: 0;
}
.faq-row:last-child { border-bottom: none; }
.faq-q {
  display: flex; align-items: center; justify-content: space-between;
  padding: 18px 16px;
  cursor: pointer;
  font-family: var(--font-mono);
  font-weight: 700;
  font-size: 16px;
  color: var(--crt-white);
}
.faq-q .toggle {
  font-family: var(--font-mono);
  color: var(--revv-cyan);
  font-size: 18px;
}
.faq-row[open] .faq-q .toggle::before { content: '−'; }
.faq-row .faq-q .toggle::before { content: '+'; }
.faq-row[open] {
  background: var(--screen-fog);
  border-left: 4px solid var(--revv-cyan);
}
.faq-a {
  padding: 0 16px 16px;
  font-family: var(--font-mono);
  font-size: 15px;
  color: var(--crt-white);
  opacity: 0.85;
  line-height: 1.75;
}

.faq-cta-strip {
  background: var(--revv-cyan);
  padding: 32px 16px;
  display: flex;
  align-items: center;
  justify-content: center;
}
.faq-cta-strip .btn {
  background: var(--lot-black);
  color: var(--crt-white);
  border-color: var(--lot-black);
  min-width: 280px;
  text-align: center;
  display: flex; align-items: center; justify-content: center; gap: 8px;
  box-shadow: none;
}
.faq-cta-strip .btn:hover { background: var(--nitro-lime); color: var(--lot-black); border-color: var(--lot-black); }
.faq-cta-strip .check {
  display: inline-block;
  width: 14px; height: 14px;
  background: var(--nitro-lime);
  position: relative;
}
.faq-cta-strip .check::after {
  content: '';
  position: absolute;
  left: 4px; top: 1px;
  width: 4px; height: 8px;
  border: solid var(--lot-black);
  border-width: 0 2px 2px 0;
  transform: rotate(45deg);
}

/* ============= UTILITIES ============= */
.text-center { text-align: center; }
.flex-row { display: flex; gap: 16px; flex-wrap: wrap; }

/* ============= RESPONSIVE ============= */
@media (max-width: 1100px) {
  .container, .nav, .filter-section, .form-section, .specs-header,
  .verified-section, .history-section, .mech-section, .interior-section,
  .filmstrip-section .filmstrip-header, .filmstrip, .gallery-header,
  .story-section, .reserve-header, .signature-section .container, .page-header,
  section { padding-left: 32px; padding-right: 32px; }
  .hero-headline { font-size: 56px; }
  .signature-headline { font-size: 48px; }
  .stats-grid { grid-template-columns: repeat(2, 1fr); }
  .stat-card:nth-child(2) { border-right: none; }
  .feature-block { grid-template-columns: 1fr; }
  .feature-text { border-right: none; padding-right: 0; }
  .feature-grid { padding-left: 0; margin-top: 24px; }
  .timeline-row { grid-template-columns: repeat(2, 1fr); }
  .testimonials-stack { grid-template-columns: 1fr; }
  .tcard-1, .tcard-2, .tcard-3 { transform: none; margin-top: 24px; }
  .listing-grid { grid-template-columns: repeat(2, 1fr); }
  .compare-grid { grid-template-columns: 1fr; }
  .specs-header-grid, .gallery-header-grid, .reserve-grid { grid-template-columns: 1fr; }
  .specs-grid { grid-template-columns: 1fr 1fr; }
  .verified-cards { grid-template-columns: 1fr 1fr; }
  .history-grid { grid-template-columns: 1fr; }
  .history-rail { display: none; }
  .form-grid { grid-template-columns: 1fr; }
  .guarantee-grid { grid-template-columns: 1fr 1fr; }
  .filter-frame .filter-body { grid-template-columns: 1fr 1fr; }
  .footer-grid { grid-template-columns: 1fr 1fr; }
  .filmstrip-section .filmstrip-header { grid-template-columns: 1fr; }
  .hotspot-diagram { justify-self: start; }
  .tab-panel { grid-template-columns: 1fr; }
  .mech-grid { grid-template-columns: 1fr; }
  .mech-photo-grid { grid-template-columns: repeat(2, 1fr); }
}
@media (max-width: 720px) {
  .nav { flex-wrap: wrap; gap: 12px; padding: 12px 16px; }
  .nav-links { gap: 16px; flex-wrap: wrap; }
  section { padding: 56px 20px; }
  .container, .page-header, .signature-section .container, .filter-section,
  .specs-header, .verified-section, .history-section, .mech-section,
  .interior-section, .filmstrip-section .filmstrip-header, .gallery-header,
  .story-section, .form-section, .reserve-header, .hero { padding-left: 20px; padding-right: 20px; }
  .hero-headline { font-size: 36px; }
  .signature-headline { font-size: 28px; }
  .stats-grid { grid-template-columns: 1fr 1fr; }
  .stat-num { font-size: 36px; }
  .listing-grid { grid-template-columns: 1fr; }
  .specs-grid, .verified-cards, .guarantee-grid { grid-template-columns: 1fr; }
  .timeline-row { grid-template-columns: 1fr; gap: 32px; }
  .timeline-row::before { display: none; }
  .filter-frame .filter-body { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: 1fr; }
  .reserve-h1 { font-size: 26px; }
  .magenta-cta h2, .gallery-cta-close h2 { font-size: 22px; }
  .mech-photo-grid { grid-template-columns: 1fr; }
  .photo-2x2 { grid-template-columns: 1fr; }
  .verified-stamp { font-size: 64px; }
  .reserve-stamp { font-size: 48px; }
  .exterior-watermark { font-size: 48px; }
}

input.content:
// RevvLot — visual-only behavior

(function () {
  // Filter chip toggle
  document.querySelectorAll('.chip').forEach(function (chip) {
    chip.addEventListener('click', function () {
      chip.classList.toggle('active');
    });
  });

  // Interior tabs
  var tabs = document.querySelectorAll('.tab');
  if (tabs.length) {
    tabs.forEach(function (tab) {
      tab.addEventListener('click', function () {
        var target = tab.getAttribute('data-target');
        tabs.forEach(function (t) { t.classList.remove('active'); });
        tab.classList.add('active');
        document.querySelectorAll('.tab-pane').forEach(function (p) {
          p.hidden = p.id !== target;
        });
      });
    });
  }

  // Mechanical rows
  var mech = document.querySelectorAll('.mech-row');
  if (mech.length) {
    mech.forEach(function (row) {
      row.addEventListener('click', function () {
        var target = row.getAttribute('data-mech');
        mech.forEach(function (r) { r.classList.remove('active'); });
        row.classList.add('active');
        document.querySelectorAll('.mech-pane').forEach(function (p) {
          p.hidden = p.id !== target;
        });
      });
    });
  }

  // Range slider thumb drag (visual only)
  document.querySelectorAll('.range-bar').forEach(function (bar) {
    var thumbLeft = bar.querySelector('.thumb.left');
    var thumbRight = bar.querySelector('.thumb.right');
    var fill = bar.querySelector('.fill');
    if (!thumbLeft || !thumbRight || !fill) return;
    var dragging = null;
    function onMove(e) {
      if (!dragging) return;
      var rect = bar.getBoundingClientRect();
      var x = (e.touches ? e.touches[0].clientX : e.clientX) - rect.left;
      var pct = Math.max(0, Math.min(100, (x / rect.width) * 100));
      if (dragging === 'left') {
        var rightPct = parseFloat(thumbRight.style.right || '30');
        if (pct > 100 - rightPct - 4) pct = 100 - rightPct - 4;
        thumbLeft.style.left = 'calc(' + pct + '% - 6px)';
        fill.style.left = pct + '%';
      } else {
        var leftPct = parseFloat((thumbLeft.style.left || '20%').replace(/.*\(([\d.]+)%.*/, '$1'));
        if (isNaN(leftPct)) leftPct = 20;
        var rPct = 100 - pct;
        if (rPct < 0) rPct = 0;
        if (pct < leftPct + 4) rPct = 100 - (leftPct + 4);
        thumbRight.style.right = 'calc(' + rPct + '% - 6px)';
        fill.style.right = rPct + '%';
      }
    }
    function stop() { dragging = null; document.removeEventListener('mousemove', onMove); document.removeEventListener('mouseup', stop); }
    thumbLeft.addEventListener('mousedown', function () { dragging = 'left'; document.addEventListener('mousemove', onMove); document.addEventListener('mouseup', stop); });
    thumbRight.addEventListener('mousedown', function () { dragging = 'right'; document.addEventListener('mousemove', onMove); document.addEventListener('mouseup', stop); });
  });

  // Radio square selection
  document.querySelectorAll('.radio-group').forEach(function (group) {
    group.querySelectorAll('label').forEach(function (lbl) {
      lbl.addEventListener('click', function () {
        group.querySelectorAll('.radio-square').forEach(function (sq) {
          sq.style.background = 'var(--lot-black)';
        });
        var sq = lbl.querySelector('.radio-square');
        if (sq) sq.style.background = 'var(--revv-cyan)';
      });
    });
  });
})();

